-- Remove os posts placeholder semeados pela 023 antes do conteudo real.
DELETE FROM posts WHERE slug IN (
    'rag-na-pratica-construindo-um-sistema-de-busca-semantica',
    'context-engineering-e-o-novo-prompt-engineering',
    'go-channels-revisitado-padroes-que-envelheceram-bem'
);
DELETE FROM categories WHERE slug = 'ia' AND NOT EXISTS (
    SELECT 1 FROM post_category WHERE post_category.category_id = categories.id
);

