-- Posts
INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Olá! Mundo...(mais um blog de um programador no ar)', 'ola-mundo', 'Como todo mundo na programação já passou por este clichê, aqui não poderia ser diferente então o primeiro post desse blog será um Hellow world! Espero poder trazer algo de útil a alguém que por um acaso passe por aqui,…', '<p>Como todo mundo na programação já passou por este clichê, aqui não poderia ser diferente então o primeiro post desse blog será um Hellow world!</p>\r\n<p>Espero poder trazer algo de útil a alguém que por um acaso passe por aqui, mas nem de longe esse blog se destina  a me colocar em um espaço de influencer de programadores ou qualquer coisa do tipo, mas sim apenas um espeço vou escrever artigos sobre problemas que solucionei, exemplos de código e etc...</p>\r\n<p>No mais seja bem vindo e espero poder ter ajudado em algo com as contribuições que aqui deixei. </p>\r\n<p>Atenciosamente.</p>\r\n<p>&nbsp;</p>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-05-06 00:37:05', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
INSERT IGNORE INTO post_category (post_id, category_id)
SELECT posts.id, categories.id FROM posts, categories
WHERE posts.slug = 'ola-mundo' AND categories.slug = 'sem-categoria';
INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Onde aprender React ?', 'onde-aprender-react', 'Vamos lá! Em um dia qualquer estava eu a rolar o feed do Linked-In e um determinado post me chamou a atenção e achei válida a idéia de compartilhar fontes de cursos gratuitos e até mesmo pagos para ajudar a quem quer…', 'Vamos lá! Em um dia qualquer estava eu a rolar o feed do Linked-In e um determinado post me chamou a atenção e achei válida a idéia de compartilhar fontes de cursos gratuitos e até mesmo pagos para ajudar a quem quer aprender determinado conhecimento e assim sendo como referido post começo listando cursos de <strong>React</strong> que fiz e outros os quais tive como fonte de consulta. Não sou especilista em <strong>React</strong> e a um bom tempo já não trabalho com esta tecnologia mas espero que a lista abaixo sirva a quem queira se aprofundar.\r\n<h4>Matheus Battisti</h4>\r\n<iframe title=\"YouTube video player\" src=\"https://www.youtube.com/embed/FXqX7oof0I4\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>\r\n<h4>CFB Cursos</h4>\r\n<iframe title=\"YouTube video player\" src=\"https://www.youtube.com/embed/1LhX2u6_BJE\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>\r\n<h4>João Ribeiro</h4>\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-05-19 20:54:22', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
