INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como instalar o RabbitVCS no ubuntu 18.04', 'como-instalar-o-rabbitvcs-no-ubuntu-18-04', 'Caso você sendo usuário Linux e precise instalar um gerenciador de SVN temos como alternativa o RABBITVCS. São apenas dois comandos no terminal do ubuntu que seguem abaixo: sudo add-apt-repository ppa:rabbitvcs/ppa sudo…', 'Caso você sendo usuário Linux e precise instalar um gerenciador de SVN temos como alternativa o <a href=\"http://rabbitvcs.org/\"><strong>RABBITVCS</strong></a>.\r\n\r\nSão apenas dois comandos no terminal do ubuntu que seguem abaixo:\r\n\r\n<strong><span>sudo add-apt-repository ppa:rabbitvcs/ppa</span></strong>\r\n<div>\r\n<div dir=\"auto\"><strong><span>sudo apt-get install rabbitvcs-core rabbitvcs-nautilus rabbitvcs-gedit rabbitvcs-cli</span></strong></div>\r\n</div>\r\n<div dir=\"auto\"></div>\r\n<div dir=\"auto\"><strong>OBSERVAÇÃO :</strong> No segundo comando omiti a instalação do <strong><span>rabbitvcs-thunar </span></strong><span>devido ao fato de que o mesmo não era encontrado no momento da instalação e assim o software não era instalado.</span></div>\r\n<div dir=\"auto\"></div>\r\n<div dir=\"auto\">Após a instalação basta digitar o bom e velho :</div>\r\n<div dir=\"auto\"></div>\r\n<div dir=\"auto\"><span><strong>sudo apt-get update</strong></span></div>\r\n<div dir=\"auto\"></div>\r\n<div dir=\"auto\">Para deixar o sistema operacional OK. Outro ponto importante é de que você deve reiniciar a máquina para que o RabbitVCS fique visível e você possa utiliza-lo.</div>\r\n&nbsp;\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-05-25 08:57:18', 'published', NULL)
