INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Extensões Visual Studio Code para o dia a dia', 'extensoes-visual-studio-code-para-o-dia-a-dia', 'Segue uma lista das extensões que mais utilizo em meu dia a dia como desenvolvedor quando uso o editor VisualStudio Code. Live Server. Cria um localhost do arquivo que você está trabalhando e atualiza a página…', 'Segue uma lista das extensões que mais utilizo em meu dia a dia como desenvolvedor quando uso o editor VisualStudio Code.\r\n<h2><strong>Live Server.</strong></h2>\r\nCria um localhost do arquivo que você está trabalhando e atualiza a página automaticamente evitando ter dar refresh(apertar a tecla F5).\r\n<h2><strong>BookMarks.</strong></h2>\r\n\r\n\r\nÉ uma extensão que ajuda nas marcações nas linhas ou trechos de código.\r\n<h2><strong>Auto Import.</strong></h2>\r\nFacilita na importação de arquivos para dentro da sua aplicação.\r\n<h2><strong>VSCODE Icons.</strong></h2>\r\n\r\n\r\nCria ícones referentes a cada tecnologia que for usada no projeto ajudando na melhor organização e identificação.\r\n<h2><strong>GITLENS.</strong></h2>\r\n\r\n\r\nAuxilia na visualização de alterações e adições feitas no Codigo.\r\n<h2><strong>Auto Rename Tag.</strong></h2>\r\n\r\n\r\nRenomeia automaticamente as Tag HTML bastando apenas editar a tag de abertura.\r\n<h2><strong>Raibow Brackets.</strong></h2>\r\nAdiciona cores a parenteses, chaves e colchetes, cada par possui uma cor facilitando saber onde se abre ou fecha determinada TAG.\r\n<h2><strong>Surround.</strong></h2>\r\n\r\n\r\nCom esta extensão podemos selecionar um trecho de código e mandar criar uma estrutura por volta como IF, FOR, While, TRY/CATCH e etc...\r\n<h2><strong>CodeSnap.</strong></h2>\r\nGera uma imagem bonita do seu código é bem utilizada para postar em redes sociais parte de seu código, repostas em fóruns.\r\n\r\n\r\n<h2><strong>Pretier.</strong></h2>\r\nFormata automaticamente nosso código assim que salvamos o arquivo. Isso é ótimo para manter um padrão de formatação.\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-08-15 21:50:00', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
