INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como acessar o entity Manager(Doctrine) dentro de comandos no Symfony 5', 'como-acessar-o-entity-managerdoctrine-dentro-de-comandos-no-symfony-5', 'Ao termos de criar comandos personalizados no Symfony na maioria das vezes se faz necessário o uso de alguma interação no banco de dados quer seja a criação, edição ou até mesmo a exclusão de um registro. No exemplo…', 'Ao termos de criar comandos personalizados no Symfony na maioria das vezes se faz necessário o uso de alguma interação no banco de dados quer seja a criação, edição ou até mesmo a exclusão de um registro.\r\n\r\nNo exemplo abaixo vamos ver como podemos acessar o EntityManager do Doctrine e assim pode realizar as mais diversas operações que o ORM nos oferece.\r\n\r\nUtilizar os recursos do Doctrine em Commands, é bem fácil também, mas não está claro na documentação oficial como faze-lo. Assim como tudo no Symfony 5, você pode injetar serviços através do construtor de Services and Commands, então para obter o EntityManager dentro de um comando, você só precisaria injetar o EntityManagerInterface assim:\r\n\r\n\r\n<pre>&lt;?php\r\n\r\nnamespace App\\Command;\r\n\r\n// ...\r\n\r\nuse Doctrine\\ORM\\EntityManagerInterface;\r\n\r\nclass ExampleCommand extends Command\r\n{\r\n    // ...\r\n\r\n    private $entityManager;\r\n\r\n    public function __construct(EntityManagerInterface $entityManager)\r\n    {\r\n        $this-&gt;entityManager = $entityManager;\r\n\r\n        parent::__construct();\r\n    }\r\n    \r\n    // ...\r\n}</pre>\r\n\r\n<pre dir=\"ltr\"><span lang=\"pt\">O gerenciador de entidades(EntityManager) estará acessível a toda a classe e você poderá executar consultas, criar e persistir entidades como costuma fazer em controladores e serviços.\r\nVamos ver alguns exemplos:\r\nDetalhes de como criar um comando no Symfony foram omitidos por entedermos que essa parte você já tem ententimento e de que o código abaixo é bem autoexplicativo.</span></pre>\r\n\r\n<pre>&lt;?php\r\n\r\n// src/Command/ExampleCommand.php\r\nnamespace App\\Command;\r\n\r\nuse Symfony\\Component\\Console\\Command\\Command;\r\nuse Symfony\\Component\\Console\\Input\\InputInterface;\r\nuse Symfony\\Component\\Console\\Output\\OutputInterface;\r\n\r\n// 1. Import the ORM EntityManager Interface\r\nuse Doctrine\\ORM\\EntityManagerInterface;\r\n\r\nclass ExampleCommand extends Command\r\n{\r\n    // o nome do comando (a parte depois de \"bin/console\")\r\n    protected static $defaultName = \'app:run-example\';\r\n    \r\n    // 2. Exponha o EntityManager no nível de classe\r\n    private $entityManager;\r\n\r\n    public function __construct(EntityManagerInterface $entityManager)\r\n    {\r\n        // 3. Atualize o valor da variável privada entityManager por meio de injeção\r\n        $this-&gt;entityManager = $entityManager;\r\n\r\n        parent::__construct();\r\n    }\r\n    \r\n    protected function configure()\r\n    {\r\n        // ...\r\n    }\r\n\r\n    // 4. Use o entityManager no código do comando\r\n    protected function execute(InputInterface $input, OutputInterface $output)\r\n    {\r\n        $em = $this-&gt;entityManager;\r\n        \r\n        // A. Access repositories\r\n        $repo = $em-&gt;getRepository(\"App:SomeEntity\");\r\n        \r\n        // B. Search using regular methods.\r\n        $res1 = $repo-&gt;find(1);\r\n        $res2 = $repo-&gt;findBy([\'field\' =&gt; \'value\']);\r\n        $res3 = $repo-&gt;findAll();\r\n        $res4 = $repo-&gt;createQueryBuilder(\'alias\')\r\n            -&gt;where(\"alias.field = :fieldValue\")\r\n            -&gt;setParameter(\"fieldValue\", 123)\r\n            -&gt;setMaxResults(10)\r\n            -&gt;getQuery()\r\n            -&gt;getResult();\r\n        \r\n        // C. Persist and flush\r\n        $em-&gt;persist($someEntity);\r\n        $em-&gt;flush();\r\n         \r\n        return 0;\r\n    }\r\n}</pre>\r\n\r\n\r\n<strong>Referência:</strong> <a href=\"https://ourcodeworld.com/articles/read/1131/how-to-access-the-entity-manager-doctrine-inside-a-command-in-symfony-5#\">https://ourcodeworld.com/articles/read/1131/how-to-access-the-entity-manager-doctrine-inside-a-command-in-symfony-5#</a>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-10-06 08:03:12', 'published', NULL)
