INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Alternar entre múltiplas versões no PHP', 'alternar-entre-multiplas-versoes-no-php', 'Então problemas do dia-a-dia se por alguma motivo qualquer você prefere utilizar ambientes de desenvolvimento locais ao invés de containers Docker onde podemos ter os mais diversos tipos de versões da linguagem…', 'Então problemas do dia-a-dia se por alguma motivo qualquer você prefere utilizar ambientes de desenvolvimento locais ao invés de containers Docker onde podemos ter os mais diversos tipos de versões da linguagem utilizado e até mesmo outros bancos de dados vamos ver como resolve meu problema de ter em meu computador mais de uma versão do PHP Instalada.<!--more-->\r\n\r\nAtravés do comando <strong>\" php -v \"</strong> consigo observar a versão do php que está em uso:\r\n\r\n\r\n<pre>PHP 7.4.32 (cli) (built: Sep 29 2022 22:24:27) ( NTS )\r\nCopyright (c) The PHP Group\r\nZend Engine v3.4.0, Copyright (c) Zend Technologies\r\nwith Zend OPcache v7.4.32, Copyright (c), by Zend Technologies</pre>\r\n\r\n\r\nPara que possamos utilizar diversas versões do PHP em nossos computadores podemos utilizar um PPA que você pode instala-lo como mostrado abaixo:\r\n\r\n\r\n<pre>sudo add-apt-repository -y ppa:ondrej/php\r\nsudo apt atualização\r\nsudo apt instalar php7.4</pre>\r\n\r\n\r\nPara poder escolher qual será a versão padrão do sistema basta utilizar o seguinte comando:\r\n\r\n\r\n<pre>sudo update-alternatives --config php</pre>\r\n\r\n\r\nAgora só digitar o número da versão que você quer como padrão ou pressione ENTER para manter a escolha atual:\r\n\r\n\r\n<pre>Existem 4 escolhas para a alternativa php (disponibiliza /usr/bin/php).\r\n\r\n  Selecção   Caminho               Prioridade Estado\r\n------------------------------------------------------------\r\n  0            /usr/bin/php.default   100       modo automático\r\n  1            /usr/bin/php.default   100       modo manual\r\n  2            /usr/bin/php7.2        72        modo manual\r\n* 3            /usr/bin/php7.4        74        modo manual\r\n  4            /usr/bin/php8.1        81        modo manual\r\n\r\nPressione  para manter a escolha actual[*], ou digite o número da selecção:</pre>\r\n\r\n\r\nPor fim, reinicie seu servidor Apache:\r\n\r\n<code>sudo systemctl restart apache2</code>\r\n\r\nAgora, verifique se o PHP 5.6 é a versão padrão ou não:\r\n\r\n<code>php -v</code>\r\n\r\ne agora você terá a seguinte saída:\r\n<pre>PHP 7.4.32 (cli) (built: Sep 29 2022 22:24:27) ( NTS )\r\nCopyright (c) The PHP Group\r\nZend Engine v3.4.0, Copyright (c) Zend Technologies\r\n    with Zend OPcache v7.4.32, Copyright (c), by Zend Technologies\r\n</pre>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-10-06 09:57:30', 'published', NULL)
