INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Convenção de nomes utilizada no Laravel', 'convencao-de-nomes-utilizada-no-laravel', 'Tabela para consulta rápida a convenção de nomes utilizadas em projetos Laravel: O que Como Bom Ruim Controller singular ArticleController ArticlesController Route plural articles/1 article/1 Named route snake_case with…', 'Tabela para consulta rápida a convenção de nomes utilizadas em projetos Laravel:\r\n<!--more-->\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>O que</th>\r\n<th>Como</th>\r\n<th>Bom</th>\r\n<th>Ruim</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Controller</td>\r\n<td>singular</td>\r\n<td>ArticleController</td>\r\n<td><del>ArticlesController</del></td>\r\n</tr>\r\n<tr>\r\n<td>Route</td>\r\n<td>plural</td>\r\n<td>articles/1</td>\r\n<td><del>article/1</del></td>\r\n</tr>\r\n<tr>\r\n<td>Named route</td>\r\n<td>snake_case with dot notation</td>\r\n<td>users.show_active</td>\r\n<td><del>users.show-active, show-active-users</del></td>\r\n</tr>\r\n<tr>\r\n<td>Model</td>\r\n<td>singular</td>\r\n<td>User</td>\r\n<td><del>Users</del></td>\r\n</tr>\r\n<tr>\r\n<td>hasOne or belongsTo relationship</td>\r\n<td>singular</td>\r\n<td>articleComment</td>\r\n<td><del>articleComments, article_comment</del></td>\r\n</tr>\r\n<tr>\r\n<td>All other relationships</td>\r\n<td>plural</td>\r\n<td>articleComments</td>\r\n<td><del>articleComment, article_comments</del></td>\r\n</tr>\r\n<tr>\r\n<td>Table</td>\r\n<td>plural</td>\r\n<td>article_comments</td>\r\n<td><del>article_comment, articleComments</del></td>\r\n</tr>\r\n<tr>\r\n<td>Pivot table</td>\r\n<td>singular model names in alphabetical order</td>\r\n<td>article_user</td>\r\n<td><del>user_article, articles_users</del></td>\r\n</tr>\r\n<tr>\r\n<td>Colunas em tabelas</td>\r\n<td>snake_case without model name</td>\r\n<td>meta_title</td>\r\n<td><del>MetaTitle; article_meta_title</del></td>\r\n</tr>\r\n<tr>\r\n<td>Model property</td>\r\n<td>snake_case</td>\r\n<td>$model-&gt;created_at</td>\r\n<td><del>$model-&gt;createdAt</del></td>\r\n</tr>\r\n<tr>\r\n<td>Foreign key</td>\r\n<td>singular model name with _id suffix</td>\r\n<td>article_id</td>\r\n<td><del>ArticleId, id_article, articles_id</del></td>\r\n</tr>\r\n<tr>\r\n<td>Chaves primárias</td>\r\n<td>-</td>\r\n<td>id</td>\r\n<td><del>custom_id</del></td>\r\n</tr>\r\n<tr>\r\n<td>Migrações</td>\r\n<td>-</td>\r\n<td>2017_01_01_000000_create_articles_table</td>\r\n<td><del>2017_01_01_000000_articles</del></td>\r\n</tr>\r\n<tr>\r\n<td>Métodos</td>\r\n<td>camelCase</td>\r\n<td>getAll</td>\r\n<td><del>get_all</del></td>\r\n</tr>\r\n<tr>\r\n<td>Métodos em controllers</td>\r\n<td><a href=\"https://laravel.com/docs/master/controllers#resource-controllers\" rel=\"nofollow\">table</a></td>\r\n<td>store</td>\r\n<td><del>saveArticle</del></td>\r\n</tr>\r\n<tr>\r\n<td>Métodos e classes de teste</td>\r\n<td>camelCase</td>\r\n<td>testGuestCannotSeeArticle</td>\r\n<td><del>test_guest_cannot_see_article</del></td>\r\n</tr>\r\n<tr>\r\n<td>Variáveis</td>\r\n<td>camelCase</td>\r\n<td>$articlesWithAuthor</td>\r\n<td><del>$articles_with_author</del></td>\r\n</tr>\r\n<tr>\r\n<td>Collection</td>\r\n<td>descriptive, plural</td>\r\n<td>$activeUsers = User::active()-&gt;get()</td>\r\n<td><del>$active, $data</del></td>\r\n</tr>\r\n<tr>\r\n<td>Object</td>\r\n<td>descriptive, singular</td>\r\n<td>$activeUser = User::active()-&gt;first()</td>\r\n<td><del>$users, $obj</del></td>\r\n</tr>\r\n<tr>\r\n<td>Config e arquivos de linguagem</td>\r\n<td>snake_case</td>\r\n<td>articles_enabled</td>\r\n<td><del>ArticlesEnabled; articles-enabled</del></td>\r\n</tr>\r\n<tr>\r\n<td>View</td>\r\n<td>kebab-case</td>\r\n<td>show-filtered.blade.php</td>\r\n<td><del>showFiltered.blade.php, show_filtered.blade.php</del></td>\r\n</tr>\r\n<tr>\r\n<td>Config</td>\r\n<td>snake_case</td>\r\n<td>google_calendar.php</td>\r\n<td><del>googleCalendar.php, google-calendar.php</del></td>\r\n</tr>\r\n<tr>\r\n<td>Contract (interface)</td>\r\n<td>adjective or noun</td>\r\n<td>Authenticatable</td>\r\n<td><del>AuthenticationInterface, IAuthentication</del></td>\r\n</tr>\r\n<tr>\r\n<td>Trait</td>\r\n<td>adjective</td>\r\n<td>Notifiable</td>\r\n<td><del>NotificationTrait</del></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\nFonte: <a href=\"https://github.com/jonaselan/laravel-best-practices#siga-a-conven%C3%A7%C3%A3o-de-nomes-usada-no-laravel\">https://github.com/jonaselan/laravel-best-practices#siga-a-conven%C3%A7%C3%A3o-de-nomes-usada-no-laravel</a>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-10-06 14:15:02', 'published', NULL)
