VALUES ('Alterar função ONCLICK de um botão com JavaScript Vanilla', 'alterar-funcao-onclick-de-um-botao-com-javascript-vanilla', 'Vamos lá a mais um estudo de caso. Na tela abaixo temos um crud simples cujo frontend foi feito com Vanilla JavaScript e assim surgiu-se a necessidade de que ao clicar no botão atualiza o evento ONCLICK do botão…', 'Vamos lá a mais um estudo de caso.\r\n\r\nNa tela abaixo temos um crud simples cujo frontend foi feito com Vanilla JavaScript e assim surgiu-se a necessidade de que ao clicar no botão atualiza o evento <strong>ONCLICK</strong> do botão registrar tivesse sua função modificada e seu texto alterado.<!--more-->\r\n\r\n\r\n\r\nO Código do botão REGISTRAR está da seguinte forma:\r\n<pre>&lt;button type=\"button\" onclick=\"salvar()\"&gt;Registrar&lt;/button&gt;</pre>\r\nAo clicarmos em um dos botões de edição na tabela ao o botão de registro deve ter seu texto alterado para EDITAR e a função do evento ONCLICK alterada para \" editar({id_do_produto}) \" e para isso adotamos a seguinte solução nos botões responsáveis pela edição dos cadastros:\r\n<pre>/* Esta função chamada \'MOSTRAR\' faz uma solicitação via GET mostrar o texto no input e alterar a função do botão de confirmação da ação */\r\nconst mostrar = (id) =&gt; {\r\n\r\n    // Solicitação GET.\r\n    fetch(`/api/produtos/${id}`,{\r\n        method: \"GET\",\r\n        headers: {\r\n            \'Content-Type\': \'application/json\',\r\n            \'X-CSRF-TOKEN\': $(\'meta[name=\"csrf-token\"]\').attr(\'content\')\r\n        }\r\n    })\r\n        // Tratamento do sucesso\r\n        .then(async (response) =&gt; {\r\n            const resultado = await response.json();\r\n            \r\n            /*Input descrição recebe o texto buscado*/\r\n            document.querySelector(\"#descricao\").value = resultado.descricao;\r\n\r\n            /*Aqui trocamos o texto do botão de Registrar para Editar*/\r\n            document.querySelector(\"#btnOperacoes\").innerHTML = \"Editar\";\r\n\r\n            /*Aqui trocamos a classe css que altera a cor do botão*/\r\n            document.querySelector(\"#btnOperacoes\").classList.remove(\"btn-success\");\r\n            document.querySelector(\"#btnOperacoes\").classList.add(\"btn-primary\");\r\n\r\n            <strong>/* Através da função set atribute pode alterar qual função deve ser aplicada ao botão escolhido */</strong>\r\n           <span><strong> document.querySelector(\"#btnOperacoes\").setAttribute(\"onclick\", `atualizar(${id})`);</strong></span>\r\n\r\n        })\r\n        .catch(err =&gt; console.log(\'Erro de solicitação\', err)); // lidar com os erros por catch\r\n    /**/\r\n\r\n}</pre>\r\n&nbsp;\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-10-13 15:29:08', 'published', NULL)
