INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Adicionar e remover classes CSS com Vanilla Javascript', 'adicionar-e-remover-classes-css-com-vanilla-javascript', 'Adicionar e remover classes CSS com JQUERY é uma atividade muito simples, mas também através do javascript puro conseguimos o mesmo efeito e com as mesma simplicidade. Todo elemento do DOM possui uma propriedade…', 'Adicionar e remover classes <strong>CSS</strong> com <strong>JQUERY</strong> é uma atividade muito simples, mas também através do javascript puro conseguimos o mesmo efeito e com as mesma simplicidade.\r\n\r\nTodo elemento do <strong>DOM</strong> possui uma propriedade classlist que é basicamente o ponto de entrada para se obter e configurar as classes <strong>CSS</strong> desse Elemento como podemos ver abaixo:\r\n\r\n<code>var classes <span>=</span> document<span>.</span><span>querySelector</span><span>(</span><span>\"#container\"</span><span>)</span><span>.</span>classList<span>;</span></code><!--more-->\r\n\r\n<strong>Adicionando uma classe CSS:</strong>\r\n\r\nUma classe CSS pode se adicionada da seguinte forma mas se a classe já existir ela será ignorada:\r\n\r\n<code>document.querySelector(\"#container\").classList.add(\'post-image\');</code>\r\n\r\nVárias classes CSS podem ser adicionadas passando vários parâmetros:\r\n<code>// add class \"post\" &amp; \"post-image\" to #container\r\ndocument.querySelector(\"#container\").classList.add(\'post\', \'post-image\');</code>\r\n\r\n<strong>Removendo uma classe CSS</strong>\r\n\r\n<code>// remove class \"post\" &amp; \"post-image\" from #container\r\ndocument.querySelector(\"#container\").classList.remove(\'post-image\');</code>\r\n\r\n<code>// remove class \"post\" &amp; \"post-image\" from #container\r\ndocument.querySelector(\"#container\").classList.remove(\'post\', \'post-image\');</code>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-10-17 07:58:11', 'published', NULL)
