INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Função para fazer a tecla ENTER funcionar como a tecla TAB em formulários web.', 'funcao-para-fazer-a-tecla-enter-funcionar-como-a-tecla-tab-em-formularios-web', 'Segue função em Jquery que utilizei muito em projetos para permitir o comportamento da tecla TAB(pular campos do formulários) utilizando a tecla enter, essa prática é muito comum em sistemas DESKTOP e acho interessante…', 'Segue função em Jquery que utilizei muito em projetos para permitir o comportamento da tecla TAB(pular campos do formulários) utilizando a tecla enter, essa prática é muito comum em sistemas DESKTOP e acho interessante a sua implementação interessante em aplicações para a Internet tb. Abaixo segue o código:\r\n\r\n\r\n<pre>$(document).ready(function() {\r\n    jQuery(\'body\').on(\'keydown\', \'input, select, textarea\', function(e) {\r\n        var self = $(this)\r\n                , form = self.parents(\'form:eq(0)\')\r\n                , focusable\r\n                , next\r\n                ;\r\n        if (e.keyCode == 13) {\r\n            focusable = form.find(\'input,select,button,textarea\').filter(\':visible\');\r\n            next = focusable.eq(focusable.index(this) + 1);\r\n            if (next.length) {\r\n                next.focus();\r\n            } else {\r\n                form.submit();\r\n            }\r\n            return false;\r\n        }\r\n    });\r\n});</pre>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-10-25 14:55:55', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
