INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como ignorar permissões do Linux em repositórios GIT.', 'como-ignorar-permissoes-do-linux-em-repositorios-git', 'Recentemente me deparei com um problema curioso que ocorre no GIT principalmente enquanto escrevemos código em modo root e depois fazemos o push para os repositórios que faz com que as permissões(CHMOD) de arquivos e…', 'Recentemente me deparei com um problema curioso que ocorre no GIT principalmente enquanto escrevemos código em modo root e depois fazemos o push para os repositórios que faz com que as permissões(CHMOD) de arquivos e pastas fossem para o servidor e ao baixar o projetos estas acabavam por atrapalhar o desenvolvimento tendo que em alguns momentos recorrer a reescrita das permissões dessas pastas CHMOD 777 e assim depois de algumas buscas e conversas com amigos chegamos a seguinte solução que é muito simples por sinal e basta seguir os comandos abaixo:<!--more-->\r\n\r\nPara solucionar isso, descobri que existe uma configuração no GIT que faz as modificações de permissões serem ignoradas. Ele permite configurar localmente (por projeto/repositório) ou globalmente.\r\n\r\n<strong>Globalmente:</strong>\r\n\r\n\r\n<pre>git config --global core.filemode false</pre>\r\n\r\n\r\n<strong>Localmente:</strong>\r\n\r\n\r\n<pre>git config core.filemode false</pre>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-11-03 20:54:41', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
