INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como resolver o erro \"oauth-private.key does not exist or is not readable\" no Laravel', 'como-resolver-o-erro-oauth-private-key-does-not-exist-or-is-not-readable-no-laravel', 'O Laravel Passport é uma biblioteca que trabalha com o padrão OAuth2 e fornece uma implementação completa do servidor OAuth2. Nesse padrão é determinada a forma de efetuar a autenticação de aplicações WEB (API) através…', 'O <strong>Laravel Passport</strong> é uma biblioteca que trabalha com o padrão OAuth2 e fornece uma implementação completa do servidor OAuth2. Nesse padrão é determinada a forma de efetuar a autenticação de aplicações WEB (API) através de tokens.<!--more-->\r\n\r\nEm alguns momentos principalmente quando devemos clonar o projeto de um reposítório GIT ou até mesmo por a aplicação em produção é comum encontrarmos o seguinte erro <strong>\"oauth-private.key does not exist or is not readable\"</strong> que pode ser facilmente corrigido seguindo os passos abaixo:\r\n\r\n<strong>Passo 1:</strong>\r\nphp artisan passport:install\r\n\r\n<strong><span lang=\"pt\">*Execute apenas se oauth-private.key e oauth-public.key não existirem na pasta de armazenamento, caso contrário, pule a primeira etapa.</span></strong>\r\n\r\n<strong>Passo 2:</strong>\r\nphp artisan config:clear\r\nphp artisan key:generate\r\nphp artisan config:clear\r\n\r\n<strong>Passo 3:</strong>\r\nAlterar permissões:\r\n\r\nsudo chown www-data:www-data storage/oauth-*.key\r\nsudo chmod 600 storage/oauth-*.key\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-11-06 09:46:20', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
