INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como instalar o Go Language no Ubuntu ?', 'como-instalar-o-go-language-no-ubuntu', 'Então resolvi tirar um tempo para conhecer outras linguagens de programação e no momento resolvi iniciar com a GO pois foge a uma série de padrões de programação na qual já estou acostumado e as etapas desse processo de…', 'Então resolvi tirar um tempo para conhecer outras linguagens de programação e no momento resolvi iniciar com a <a href=\"https://go.dev/\"><strong>GO</strong></a> pois foge a uma série de padrões de programação na qual já estou acostumado e as etapas desse processo de aprendizado serão postadas aqui neste espaço. Então vamos lá.\r\n\r\nVocê pode fazer o download do instalador no seguinte link: <a href=\"https://go.dev/doc/install\">https://go.dev/doc/install</a>\r\n\r\nO Link acima te dará os passos necessários para o download e instalação mas faço uns comentários adicionais abaixo que podem servir.\r\n\r\nCaso você tenha feito alguma tentativa anterior de instalação basta remover a pasta /usr/local/go (se existir) e extraia o arquivo que você acabou de baixar em /usr/local, criando uma nova árvore Go em /usr/local/go:\r\n\r\n<code>$ rm -rf /usr/local/go &amp;&amp; tar -C /usr/local -xzf go1.19.3.linux-amd64.tar.gz</code>\r\n\r\nAgora vamos ao passo 02 que adicionar o local de instalação as variáveis de ambiente do linux\r\n\r\nAbra o terminal do Linux com CTRL+ALT+T\r\nUtilize os comandos abaixo para abrir o arquivo .profile\r\n\r\n<code>$ cd\r\n$ gedit .profile</code>\r\n\r\nO arquivo será aberto dentro do editor de texto básico do Linux na última linha adicione:\r\n\r\n<code>export PATH=$PATH:/usr/local/go/bin</code>\r\n\r\nSalve e feche o aquico e assim as variáveis de ambiemte do Linux serão atualizadas. Só de fazer a alteração o GO ainda não será reconhecido pelo terminal então volte ao terminal e digite o comando:\r\n\r\n<code>$ source .profile</code>\r\n\r\nAgora o GO passará a ser reconhecido e para testar a interpretação pelo terminal use:\r\n\r\n<code>$ go version</code>\r\n\r\nO comando utilizado anteriormente irá retorna a versão instalada e caso queira ainda verificar outras configurações referentes ao GO temos:\r\n\r\n<code>$ go env</code>\r\n\r\nAo fechar o terminal e abri-lo novamente o GO ainda não será interpretado sendo necessário repetir o comando <strong>\" $ source .profile \"</strong> isso se resolve bastando apenas reiniciar seu computador.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2022-11-12 12:18:21', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
