INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como atualizar multiplos registros com o método whereIn no Laravel 9 ?', '203-2', 'O Laravel 9 é um framework PHP moderno e poderoso que oferece muitas ferramentas úteis para desenvolvedores web. Uma das funcionalidades mais comuns em aplicações web é a atualização de vários registros ao mesmo tempo.…', 'O Laravel 9 é um framework PHP moderno e poderoso que oferece muitas ferramentas úteis para desenvolvedores web. Uma das funcionalidades mais comuns em aplicações web é a atualização de vários registros ao mesmo tempo. Felizmente, o Laravel 9 torna essa tarefa muito fácil e eficiente com o método whereIn.\r\n\r\nO método whereIn permite selecionar um conjunto de registros com base em uma lista de valores. Por exemplo, imagine que você tenha uma tabela de usuários e queira atualizar o status de vários usuários ao mesmo tempo. Você pode usar o método whereIn para selecionar todos os usuários com base em seus IDs e, em seguida, atualizar o status deles.\r\n\r\nVamos dar uma olhada em um exemplo completo para ilustrar como isso funciona. Suponha que você tenha uma tabela de usuários com as colunas id, name e status. Para atualizar o status de vários usuários ao mesmo tempo, você pode usar o seguinte código:\r\n<blockquote><span>$userIds = [1, 2, 3, 4, 5];</span>\r\n\r\n<span>DB::table(\'users\')</span>\r\n<span>-&gt;whereIn(\'id\', $userIds)</span>\r\n<span>-&gt;update([\'status\' =&gt; \'ativo\']);</span></blockquote>\r\nNesse exemplo, estamos selecionando todos os usuários cujos IDs estão contidos na lista <code>$userIds</code> e, em seguida, atualizando o status deles para \"ativo\". Observe que usamos o método <code>update</code> para efetivamente atualizar os registros.\r\n\r\nO método <code>whereIn</code> também pode ser usado em conjunto com outros métodos de consulta, como <code>where</code>, <code>orderBy</code>, <code>limit</code> e <code>offset</code>. Isso permite que você crie consultas mais avançadas e personalizadas para atender às suas necessidades específicas.\r\n\r\nAlém disso, o Laravel 9 também oferece suporte a consultas preparadas, o que ajuda a evitar ataques de injeção de SQL e melhora a segurança do seu aplicativo.\r\n\r\nEm resumo, o método <code>whereIn</code> do Laravel 9 é uma ferramenta poderosa para atualizar vários registros em uma única operação. Ele permite que você selecione registros com base em uma lista de valores e os atualize de forma eficiente e segura. Combinado com outros métodos de consulta do Laravel, você pode criar consultas personalizadas e avançadas para atender às suas necessidades específicas.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2023-03-28 08:55:56', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
