VALUES ('Criando uma nova branch a partir da develop pelo terminal com GIT', 'criando-uma-nova-branch-a-partir-da-develop-pelo-terminal-com-git', 'Para criar uma nova branch a partir da branch develop usando o terminal com o Git, siga os seguintes passos: Certifique-se de estar na branch develop executando o comando git checkout develop. Crie uma nova branch a…', 'Para criar uma nova branch a partir da branch <code>develop</code> usando o terminal com o Git, siga os seguintes passos:\r\n<ol>\r\n 	<li>Certifique-se de estar na branch <code>develop</code> executando o comando <code>git checkout develop</code>.</li>\r\n 	<li>Crie uma nova branch a partir da <code>develop</code> usando o comando <code>git checkout -b nome_da_nova_branch</code>.</li>\r\n 	<li>Faça as alterações necessárias na nova branch.</li>\r\n 	<li>Quando estiver pronto para fazer o merge de sua nova branch na <code>develop</code>, execute o comando <code>git checkout develop</code> para voltar para a branch <code>develop</code>.</li>\r\n 	<li>Em seguida, execute o comando <code>git merge nome_da_nova_branch</code> para fazer o merge da nova branch na <code>develop</code>.</li>\r\n 	<li>Finalmente, execute o comando <code>git push</code> para enviar as alterações para o repositório remoto.</li>\r\n</ol>\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2023-03-28 11:21:30', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
