INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Script para automatizar as instalações de extensões do php em distribuições LINUX', 'script-automatizar-instalacoes-de-extensoes-php-linux', 'Publiquei neste artigo https://paulorb.dev/alternar-entre-multiplas-versoes-no-php/ formas de como instalar diversas versões do PHP em distros Linux mas surgiu um problema que uma série de extensões do php não estavam…', 'Publiquei neste artigo <a href=\"https://paulorb.dev/alternar-entre-multiplas-versoes-no-php/\">https://paulorb.dev/alternar-entre-multiplas-versoes-no-php/</a> formas de como instalar diversas versões do PHP em distros Linux mas surgiu um problema que uma série de extensões do php não estavam presentes e que eram fundamentais para o funcionamento de qualquer projeto php então para facilitar a vida e evitar de ficar instalando uma a uma montei o seguinte script:\r\n\r\nO Código pode ser escritor em qualquer editor de texto e salva com a extensão .sh\r\n\r\n\r\n<pre>#!/bin/bash\r\n\r\n# List of PHP extensions to install\r\nphp_extensions=(\r\n    bcmath\r\n    bz2\r\n    calendar\r\n    Core\r\n    ctype\r\n    curl\r\n    date\r\n    dom\r\n    exif\r\n    FFI\r\n    fileinfo\r\n    filter\r\n    ftp\r\n    gd\r\n    gettext\r\n    hash\r\n    iconv\r\n    igbinary\r\n    intl\r\n    json\r\n    libxml\r\n    mbstring\r\n    mysqli\r\n    mysqlnd\r\n    openssl\r\n    pcntl\r\n    pcre\r\n    PDO\r\n    pdo_mysql\r\n    pdo_pgsql\r\n    pdo_sqlite\r\n    pgsql\r\n    Phar\r\n    posix\r\n    random\r\n    readline\r\n    redis\r\n    Reflection\r\n    session\r\n    shmop\r\n    SimpleXML\r\n    sockets\r\n    sodium\r\n    SPL\r\n    sqlite3\r\n    standard\r\n    sysvmsg\r\n    sysvsem\r\n    sysvshm\r\n    tokenizer\r\n    xdebug\r\n    xml\r\n    xmlreader\r\n    xmlwriter\r\n    xsl\r\n    Zend OPcache\r\n    zip\r\n    zlib\r\n)\r\n\r\n# Install PHP extensions\r\n# substituir a versão do PHP conforme sua necessidade.\r\nfor extension in \"${php_extensions[@]}\"; do\r\n    sudo apt install -y php8.1-\"$extension\"\r\ndone\r\n</pre>\r\n\r\n\r\nApós escrever o código salve o arquivo com o nome install_php_extensions.sh e feito isso abra o terminal do linux dentro da pasta onde você salvou o script e o torne executável com o seguinte comando:\r\n<blockquote>chmod +x install_php_extensions.sh</blockquote>\r\nEntão execute o script com permissões de administrador conforme o exemplo:\r\n<blockquote>sudo ./install_php_extensions.sh</blockquote>\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2023-07-27 18:00:33', 'published', NULL)
