INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Habilitar Sudo no Debian e seus derivados', 'habilitar-sudo-no-debian-e-seus-derivados', 'Por padrão o debian não trás o sudo habilitado como estamos acostumados no Ubuntu e outro de seus derivados como o Mint, Xubuntu ou Kubuntu. Para habilitar este comando como o já conhecemos devemos seguir os seguintes…', 'Por padrão o debian não trás o sudo habilitado como estamos acostumados no Ubuntu e outro de seus derivados como o Mint, Xubuntu ou Kubuntu. Para habilitar este comando como o já conhecemos devemos seguir os seguintes passos:\r\n\r\n1 - Abra o terminal;\r\n\r\n2 - Consiga privilégios de administrador através do comando :\r\n<blockquote>su -</blockquote>\r\n3 - Instale o sudo dos repositórios do Debian:\r\n<blockquote>apt install sudo</blockquote>\r\n4 - Editar o arquivo /etc/sudoers:\r\n<blockquote>nano /etc/sudoers</blockquote>\r\n5 - Este arquivo não possui muitas linhas procure pela linha onde esta escrito <strong>root ALL=(ALL:ALL) ALL</strong> e sob esta linha adicione seu usuario:\r\n<blockquote>nome-usuario ALL=(ALL:ALL) ALL</blockquote>\r\n6 - Após ter feito isso salve(CTRL+O) e feche o documento(CTRL+X).\r\n\r\nApós a execução desses passos você poderá usar o sudo normalmente.\r\n\r\nUm ponto a ser observado que em servidores tal prática não é recomendada pois vai de encontro as políticas de segurança do Debian pois o que o <strong>SUDO</strong> faz na verdade é dar permissões de um usuário a outro que é justamente o que é feito aqui onde temos os privilégios do usuário root sendo passados para o usuário informado na modificação do arquivo SUDOERS.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2023-08-13 17:46:39', 'published', NULL)
