INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Instalar o PGAdmin 4 em distribuições Linux Debian 12', 'instalar-o-pgadmin-4-em-distribuicoes-linux-debian-12', 'Recentemente enquanto utilizava o Linux Mint 21 Vera tive uma série de problemas ao instalar o PGAdmin 4 e numa conversa com um colega de trabalho surgiu a oportunidade de vir a utilizar o Debian. A recomendação inicial…', 'Recentemente enquanto utilizava o Linux Mint 21 Vera tive uma série de problemas ao instalar o PGAdmin 4 e numa conversa com um colega de trabalho surgiu a oportunidade de vir a utilizar o Debian. A recomendação inicial era usar o Debian 11 mas devido a incompatibilidade de Hardware tive mais sucesso com o Debian 12 BookWorm.\r\n\r\nEnfim, vamos aos passos:\r\n\r\n<strong>1. Instalar o repositório padrão do PGAdmin</strong>\r\n<blockquote>echo \\ \"deb https://ftp.postgresql.org/pub/pgadmin/pgadmin4/apt/$(lsb_release -cs) pgadmin4 main\" \\ &gt; /etc/apt/sources.list.d/pgadmin4.list</blockquote>\r\n<strong>2. Instale a chave de assinatura GPG do repositório pgAdmin</strong>\r\n<blockquote>apt install gnupg2 curl\r\n\r\ncurl -fsS https://www.pgadmin.org/static/packages_pgadmin_org.pub \\ | sudo gpg --dearmor -o /etc/apt/trusted.gpg.d/packages-pgadmin-org.gpg</blockquote>\r\n<strong>3. Agora, atualize o cache de pacotes do sistema e instale o pgAdmin no Debian 12;</strong>\r\n<blockquote>apt update</blockquote>\r\n<strong>4. Instale nos modos desktop e Web.</strong>\r\n<blockquote>apt install pgadmin4</blockquote>\r\n<strong>5. Ou somente o modo desktop.</strong>\r\n<blockquote>apt install pgadmin4-desktop</blockquote>\r\nSimples assim em um momento oportuno irei trazer para o blog a solução que tive para fazer no Mint que mencionei no início do texto. Espero ter ajudado.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2023-08-22 20:57:24', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
