INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Script para automatizar instalações de ferramentas em ambiente LINUX', 'script-para-automatizar-instalacoes-de-ferramentas-em-ambiente-linux', 'Para agilizar as instalações das minhas ferramentas de desenvolvimento quando for necessário resolvi montar o seguinte script: #!/bin/bash # Função para instalar o PHP e suas extensões install_php_and_extensions() {…', 'Para agilizar as instalações das minhas ferramentas de desenvolvimento quando for necessário resolvi montar o seguinte script:\r\n\r\n\r\n<pre>#!/bin/bash\r\n\r\n# Função para instalar o PHP e suas extensões\r\ninstall_php_and_extensions() {\r\n    local php_version=\"$1\"\r\n    local php_extensions=(\r\n        bcmath\r\n        bz2\r\n        calendar\r\n        Core\r\n        ctype\r\n        curl\r\n        date\r\n        dom\r\n        exif\r\n        FFI\r\n        fileinfo\r\n        filter\r\n        ftp\r\n        gd\r\n        gettext\r\n        hash\r\n        iconv\r\n        igbinary\r\n        intl\r\n        json\r\n        libxml\r\n        mbstring\r\n        mysqli\r\n        mysqlnd\r\n        openssl\r\n        pcntl\r\n        pcre\r\n        PDO\r\n        pdo_mysql\r\n        pdo_pgsql\r\n        pdo_sqlite\r\n        pgsql\r\n        Phar\r\n        posix\r\n        random\r\n        readline\r\n        redis\r\n        Reflection\r\n        session\r\n        shmop\r\n        SimpleXML\r\n        sockets\r\n        sodium\r\n        SPL\r\n        sqlite3\r\n        standard\r\n        sysvmsg\r\n        sysvsem\r\n        sysvshm\r\n        tokenizer\r\n        xdebug\r\n        xml\r\n        xmlreader\r\n        xmlwriter\r\n        xsl\r\n        \"Zend OPcache\"\r\n        zip\r\n        zlib\r\n    )\r\n\r\n    # Adiciona o PPA do PHP\r\n    sudo add-apt-repository -y ppa:ondrej/php\r\n    sudo apt update\r\n\r\n    # Instala o PHP\r\n    sudo apt install -y php\"$php_version\"\r\n\r\n    # Instala as extensões do PHP\r\n    for extension in \"${php_extensions[@]}\"; do\r\n        sudo apt install -y \"php$php_version-$extension\"\r\n    done\r\n}\r\n\r\n# Função para instalar o CURL\r\ninstall_curl() {\r\n    sudo apt install -y curl\r\n}\r\n\r\n# Função para instalar o WGET\r\ninstall_wget() {\r\n    sudo apt install -y wget\r\n}\r\n\r\n# Função para instalar o Docker e o Docker Compose\r\ninstall_docker_and_compose() {\r\n    sudo apt update\r\n    sudo apt install docker.io \r\n    sudo curl -L \"https://github.com/docker/compose/releases/download/1.25.4/docker-compose-$(uname -s)-$(uname -m)\" -o /usr/local/bin/docker-compose \r\n    sudo chmod +x /usr/local/bin/docker-compose\r\n    sudo groupadd docker\r\n    sudo usermod -aG docker $USER \r\n    newgrp docker\r\n    docker run hello-world\r\n    sudo systemctl enable docker.service\r\n    sudo systemctl enable containerd.service\r\n}\r\n\r\n# Função para instalar o Redis\r\ninstall_redis() {\r\n    sudo apt update\r\n    sudo apt install -y redis-server\r\n    sudo systemctl start redis-server\r\n    sudo systemctl enable redis-server\r\n}\r\n\r\n# Função para instalar o Node.js usando o NVM\r\ninstall_nodejs() {\r\n    install_nvm\r\n    nvm install node\r\n}\r\n\r\n# Função para instalar o FileZilla\r\ninstall_filezilla() {\r\n    sudo apt update\r\n    sudo apt install -y filezilla\r\n}\r\n\r\n# Função para instalar o PhpStorm\r\ninstall_phpstorm() {\r\n    sudo snap install phpstorm --classic\r\n}\r\n\r\n# Função para instalar o Python e o PIP\r\ninstall_python_and_pip() {\r\n    sudo apt update\r\n    sudo apt install -y python3\r\n    python3 --version\r\n    sudo apt install -y python3-pip\r\n}\r\n\r\n# Função para instalar o NVM\r\ninstall_nvm() {\r\n    wget -qO- https://raw.githubusercontent.com/nvm-sh/nvm/v0.39.7/install.sh | bash\r\n    export NVM_DIR=\"$([ -z \"${XDG_CONFIG_HOME-}\" ] &amp;&amp; printf %s \"${HOME}/.nvm\" || printf %s \"${XDG_CONFIG_HOME}/nvm\")\"\r\n    [ -s \"$NVM_DIR/nvm.sh\" ] &amp;&amp; \\. \"$NVM_DIR/nvm.sh\" # This loads nvm\r\n}\r\n\r\n# Função para instalar o Postman\r\ninstall_postman() {\r\n    sudo apt update\r\n    sudo apt install -y snapd\r\n    sudo snap install postman\r\n}\r\n\r\n\r\n\r\n# Menu de opções\r\nwhile true; do\r\n    echo \"Selecione a ferramenta a ser instalada:\"\r\n    echo \"1. PostgreSQL com pgAdmin\"\r\n    echo \"2. Apache\"\r\n    echo \"3. PHP\"\r\n    echo \"4. DBeaver\"\r\n    echo \"5. Git\"\r\n    echo \"6. Visual Studio Code\"\r\n    echo \"7. Google Chrome\"\r\n    echo \"8. Docker e Docker Compose\"\r\n    echo \"9. CURL\"\r\n    echo \"10. WGET\"\r\n    echo \"11. Python e PIP\"\r\n    echo \"12. NVM\"\r\n    echo \"13. Redis\"\r\n    echo \"14. Node.js\"\r\n    echo \"15. FileZilla\"\r\n    echo \"16. PhpStorm\"\r\n    echo \"17. Postman\"\r\n    echo \"18. Sair\"\r\n\r\n    read -p \"Digite o número correspondente à opção desejada: \" option\r\n\r\n    case $option in\r\n        1)  # Instala PostgreSQL com pgAdmin\r\n            curl -fsS https://www.pgadmin.org/static/packages_pgadmin_org.pub | sudo gpg --dearmor -o /usr/share/keyrings/packages-pgadmin-org.gpg\r\n            sudo sh -c \'echo \"deb [signed-by=/usr/share/keyrings/packages-pgadmin-org.gpg] https://ftp.postgresql.org/pub/pgadmin/pgadmin4/apt/$(lsb_release -cs) pgadmin4 main\" &gt; /etc/apt/sources.list.d/pgadmin4.list &amp;&amp; apt update\'\r\n            sudo apt install -y curl ca-certificates\r\n            sudo apt install -y pgadmin4 pgadmin4-desktop pgadmin4-web\r\n\r\n            # Instala o PostgreSQL e define o usuário e senha padrão\r\n            sudo apt install -y postgresql postgresql-contrib\r\n            sudo -u postgres psql -c \"ALTER USER postgres WITH PASSWORD \'postgres\';\"\r\n            sudo systemctl restart postgresql\r\n            sudo /usr/pgadmin4/bin/setup-web.sh\r\n            ;;\r\n        2)  # Instala Apache\r\n            sudo apt update\r\n            sudo apt install -y apache2\r\n            sudo systemctl status apache2\r\n            ;;\r\n        3)  # Instala PHP\r\n            read -p \"Digite a versão do PHP que deseja instalar (exemplo: 8.2): \" php_version\r\n            install_php_and_extensions \"$php_version\"\r\n            ;;\r\n        4)  # Instala DBeaver\r\n            wget -O - https://dbeaver.io/debs/dbeaver.gpg.key | sudo apt-key add -\r\n            echo \"deb https://dbeaver.io/debs/dbeaver-ce /\" | sudo tee /etc/apt/sources.list.d/dbeaver.list\r\n            sudo apt update\r\n            sudo apt install -y dbeaver-ce\r\n            ;;\r\n        5)  # Instala Git\r\n            sudo apt install -y git\r\n            ;;\r\n        6)  # Instala Visual Studio Code\r\n            sudo apt update\r\n            sudo apt install -y software-properties-common apt-transport-https wget\r\n            wget -q https://packages.microsoft.com/keys/microsoft.asc -O- | sudo apt-key add -\r\n            sudo add-apt-repository \"deb [arch=amd64] https://packages.microsoft.com/repos/vscode stable main\"\r\n            sudo apt update\r\n            sudo apt install -y code\r\n            ;;\r\n        7)  # Instala Google Chrome\r\n            wget https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb\r\n            sudo apt update\r\n            sudo apt install -y ./google-chrome-stable_current_amd64.deb\r\n            ;;\r\n        8)  # Instala Docker e Docker Compose\r\n            install_docker_and_compose\r\n            ;;\r\n        9)  # Instala CURL\r\n            install_curl\r\n            ;;\r\n        10) # Instala WGET\r\n            install_wget\r\n            ;;\r\n        11) # Instala Python e PIP\r\n            install_python_and_pip\r\n            ;;\r\n        12) # Instala NVM\r\n            install_nvm\r\n            ;;\r\n        13) # Instala Redis\r\n            install_redis\r\n            ;;\r\n        14) # Instala Node.js\r\n            install_nodejs\r\n            ;;\r\n        15) # Instala FileZilla\r\n            install_filezilla\r\n            ;;\r\n        16) # Instala PhpStorm\r\n            install_phpstorm\r\n            ;;\r\n        17) # Instala PhpStorm\r\n            install_postman\r\n            ;;    \r\n        18) # Sai do script\r\n            echo \"Saindo...\"\r\n            exit\r\n            ;;\r\n        *)  # Opção inválida\r\n            echo \"Opção inválida. Por favor, selecione uma opção válida.\"\r\n            ;;\r\n    esac\r\ndone\r\n</pre>\r\n\r\n\r\nBasta colocar o código mostrado em um arquivo de texto e depois salva-lo com o nome de sua escolha no meu caso eu chamei de \"ambiente.sh\" feito isso basta abrir o terminal da sua distribuição linux e dar a permissões de execução com o comando \"sudo chmos +x ambiente.sh\" e depois executar o arquivo com o comando ./ambiente.sh no mesmo terminal com um menu de opções aí basta escolher a ferramenta a ser instalada e pronto.\r\n\r\n\r\n<pre>paulo@paulo-Inspiron-15-3520:~/Área de Trabalho$ ./install.sh \r\nSelecione a ferramenta a ser instalada:\r\n1. PostgreSQL com pgAdmin\r\n2. Apache\r\n3. PHP\r\n4. DBeaver\r\n5. Git\r\n6. Visual Studio Code\r\n7. Google Chrome\r\n8. Docker e Docker Compose\r\n9. CURL\r\n10. WGET\r\n11. Python e PIP\r\n12. NVM\r\n13. Redis\r\n14. Node.js\r\n15. FileZilla\r\n16. PhpStorm\r\n17. Postman\r\n18. Sair\r\nDigite o número correspondente à opção desejada: \r\n</pre>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-03-29 17:43:59', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
