INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como instalar o DBEAVEr via PPA no Ubuntu Linux e derivados.', 'como-instalar-o-dbeaver-via-ppa-no-ubuntu-linux-e-derivados', 'Vamos a mais um post HOW TO.... Abra o Terminal: Você pode fazer isso procurando por \"Terminal\" no menu de aplicativos ou pressionando Ctrl+Alt+T. Adicione o PPA do DBeaver à sua lista de repositórios: Execute o…', 'Vamos a mais um post HOW TO....\r\n\r\n<strong>Abra o Terminal:</strong> Você pode fazer isso procurando por \"Terminal\" no menu de aplicativos ou pressionando <code>Ctrl+Alt+T</code>.\r\n\r\n<strong>Adicione o PPA do DBeaver à sua lista de repositórios:</strong> Execute o seguinte comando no terminal:\r\n\r\n\r\n<pre>sudo add-apt-repository ppa:serge-rider/dbeaver-ce</pre>\r\n\r\n\r\nPara instalar o DBeaver no Linux Mint ou qualquer outra distribuição baseada no Ubuntu via PPA, você precisa adicionar o repositório PPA do DBeaver à sua lista de fontes de software e então instalar o pacote. Aqui estão as etapas detalhadas:\r\n<ol>\r\n 	<li><strong>Abra o Terminal:</strong> Você pode fazer isso procurando por \"Terminal\" no menu de aplicativos ou pressionando <code>Ctrl+Alt+T</code>.</li>\r\n 	<li><strong>Adicione o PPA do DBeaver à sua lista de repositórios:</strong> Execute o seguinte comando no terminal:</li>\r\n</ol>\r\n<div>\r\n<div>\r\n\r\n\r\n<pre>sudo add-apt-repository ppa:serge-rider/dbeaver-ce</pre>\r\n\r\n\r\n</div>\r\n</div>\r\nEste comando adiciona o PPA oficial do DBeaver Community Edition (CE) à sua lista de fontes de software. Você precisará inserir sua senha e confirmar a adição pressionando Enter quando solicitado.\r\n\r\n<strong>Atualize a lista de pacotes:</strong> Após adicionar o PPA, é uma boa prática atualizar a lista de pacotes disponíveis para garantir que seu sistema esteja ciente do novo repositório. Faça isso executando:\r\n\r\n\r\n<pre>sudo apt-get update\r\n</pre>\r\n\r\n\r\n<strong>Instale o DBeaver:</strong> Com o repositório adicionado e a lista de pacotes atualizada, agora você pode instalar o DBeaver usando o seguinte comando:\r\n\r\n\r\n<pre>sudo apt-get install dbeaver-ce</pre>\r\n\r\n\r\n<strong>Inicie o DBeaver:</strong> Após a instalação, você pode iniciar o DBeaver através do menu de aplicativos do seu sistema, procurando por \"DBeaver\", ou pode iniciar pelo terminal com o comando <code>dbeaver</code>.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-04-09 13:34:42', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
