INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('A função WITH RECURSIVE no PostgreSQL', 'a-funcao-with-recursive-no-postgresql', 'A função WITH RECURSIVE no PostgreSQL é uma ferramenta poderosa para a execução de consultas recursivas em bancos de dados. Este recurso é especialmente útil quando se trabalha com dados hierárquicos ou relacionais,…', 'A função <code>WITH RECURSIVE</code> no PostgreSQL é uma ferramenta poderosa para a execução de consultas recursivas em bancos de dados. Este recurso é especialmente útil quando se trabalha com dados hierárquicos ou relacionais, como árvores de categorias, estruturas organizacionais ou grafos. Neste artigo, vamos explorar como a função <code>WITH RECURSIVE</code> funciona e como você pode utilizá-la para resolver problemas complexos de maneira eficiente.\r\n\r\nA cláusula <code>WITH</code> é usada no PostgreSQL para criar uma expressão de tabela comum (Common Table Expression - CTE), que é uma subconsulta temporária que retorna um conjunto de resultados temporário. <code>WITH RECURSIVE</code> expande essa capacidade permitindo que essas subconsultas referenciem a si mesmas, criando uma CTE recursiva.\r\n\r\nUma CTE recursiva é composta de duas partes: a parte não recursiva e a parte recursiva. A parte não recursiva é a base da recursão, fornecendo o caso base. A parte recursiva é onde a CTE chama a si mesma, permitindo a navegação através de níveis hierárquicos.\r\n\r\nA sintaxe básica de uma consulta <code>WITH RECURSIVE</code> é a seguinte:\r\n\r\n\r\n<pre>WITH RECURSIVE nome_temporario AS (\r\n    -- Parte não recursiva\r\n    SELECT ...\r\n    UNION ALL\r\n    -- Parte recursiva\r\n    SELECT ... FROM nome_temporario WHERE ...\r\n)\r\nSELECT * FROM nome_temporario;\r\n</pre>\r\n\r\n\r\nVamos a um exemplo prático:\r\n\r\nPrimeiro, vamos definir a estrutura da tabela <code>funcionarios</code>. Esta tabela incluirá colunas para o <code>id</code> do funcionário, seu <code>nome</code>, e o <code>id</code> do seu gerente (<code>id_gerente</code>), onde <code>id_gerente</code> é uma referência ao <code>id</code> de outro funcionário que atua como seu gerente.\r\n\r\n\r\n<pre>CREATE TABLE funcionarios (\r\n    id SERIAL PRIMARY KEY,\r\n    nome VARCHAR(255) NOT NULL,\r\n    id_gerente INTEGER,\r\n    FOREIGN KEY (id_gerente) REFERENCES funcionarios(id)\r\n);\r\n</pre>\r\n\r\n\r\nEm seguida, inseriremos alguns dados de exemplo para representar uma estrutura organizacional simples. Incluiremos um gerente geral no topo e diversos níveis de gerentes e funcionários abaixo dele.\r\n\r\n\r\n<pre>INSERT INTO funcionarios (nome, id_gerente) VALUES\r\n(\'Gerente Geral\', NULL),  -- id 1\r\n(\'Gerente A\', 1),  -- id 2\r\n(\'Gerente B\', 1),  -- id 3\r\n(\'Funcionário A1\', 2),  -- id 4\r\n(\'Funcionário A2\', 2),  -- id 5\r\n(\'Funcionário B1\', 3),  -- id 6\r\n(\'Funcionário B2\', 3),  -- id 7\r\n(\'Subgerente A1\', 2),  -- id 8\r\n(\'Funcionário A1.1\', 8);  -- id 9\r\n</pre>\r\n\r\n\r\nAgora que temos nossa tabela e dados, vamos escrever uma consulta usando <code>WITH RECURSIVE</code> para listar todos os subordinados do \"Gerente Geral\", diretamente ou através de outros gerentes.\r\n\r\n\r\n<pre>WITH RECURSIVE subordinados AS (\r\n    SELECT id, nome, id_gerente\r\n    FROM funcionarios\r\n    WHERE id_gerente IS NULL  -- Caso base: o gerente geral não tem id_gerente\r\n    UNION ALL\r\n    SELECT f.id, f.nome, f.id_gerente\r\n    FROM funcionarios f\r\n    INNER JOIN subordinados s ON f.id_gerente = s.id  -- Parte recursiva\r\n)\r\nSELECT * FROM subordinados WHERE id != 1;  -- Exclui o gerente geral da lista final\r\n</pre>\r\n\r\n\r\nEsta consulta inicia com o \"Gerente Geral\" como caso base, que é o único funcionário sem <code>id_gerente</code> (indicando que não tem superior), e recursivamente inclui todos os funcionários que estão abaixo dele na hierarquia, utilizando a união (<code>UNION ALL</code>) entre a parte não recursiva e a parte recursiva da consulta. O resultado final exclui o \"Gerente Geral\" da lista para focar nos subordinados.\r\n\r\nAssim temos o resultado:\r\n<table>\r\n<tbody>\r\n<tr>\r\n<th>id</th>\r\n<th>nome</th>\r\n<th>id_gerente</th>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>Gerente A</td>\r\n<td>1</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>Gerente B</td>\r\n<td>1</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>Funcionário A1</td>\r\n<td>2</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>Funcionário A2</td>\r\n<td>2</td>\r\n</tr>\r\n<tr>\r\n<td>6</td>\r\n<td>Funcionário B1</td>\r\n<td>3</td>\r\n</tr>\r\n<tr>\r\n<td>7</td>\r\n<td>Funcionário B2</td>\r\n<td>3</td>\r\n</tr>\r\n<tr>\r\n<td>8</td>\r\n<td>Subgerente A1</td>\r\n<td>2</td>\r\n</tr>\r\n<tr>\r\n<td>9</td>\r\n<td>Funcionário A1.1</td>\r\n<td>8</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n&nbsp;\r\n\r\nEspero ter ajudo você a entender melhor a função recursive e seus uso em projetos de software.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-04-11 10:03:26', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
