INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Tutorial de Desenvolvimento: Criando um Jogo de Tetris', 'criando-um-jogo-tetris', 'E vamos a mais um tutorial de outro joguinho clássico só que dessa vez vamos recriar o Tetris. Link do repositório: https://github.com/paulodm145/tetris Estrutura do Projeto /projeto-tetris │ ├── index.html ├──…', 'E vamos a mais um tutorial de outro joguinho clássico só que dessa vez vamos recriar o Tetris.\r\n\r\nLink do repositório:<a href=\"https://github.com/paulodm145/tetris\"> https://github.com/paulodm145/tetris</a>\r\n\r\n\r\n<h3>Estrutura do Projeto</h3>\r\n/projeto-tetris\r\n│\r\n├── index.html\r\n├── styles.css\r\n└── script.js\r\n<h3>1. index.html</h3>\r\nEste arquivo contém a estrutura básica da página do jogo.\r\n\r\n\r\n<pre>&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"pt\"&gt;\r\n&lt;head&gt;\r\n    &lt;meta charset=\"UTF-8\"&gt;\r\n    &lt;title&gt;Tetris&lt;/title&gt;\r\n    &lt;link rel=\"stylesheet\" href=\"styles.css\"&gt;\r\n&lt;/head&gt;\r\n&lt;body&gt;\r\n    &lt;div&gt;\r\n        &lt;div&gt;Pontuação: &lt;span&gt;0&lt;/span&gt;&lt;/div&gt;\r\n        &lt;div&gt;&lt;/div&gt;\r\n        &lt;div&gt;\r\n            &lt;button&gt;Reiniciar&lt;/button&gt;\r\n            &lt;button&gt;Pausar&lt;/button&gt;\r\n            &lt;button&gt;Zerar Pontuação&lt;/button&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n    &lt;script src=\"script.js\"&gt;&lt;/script&gt;\r\n&lt;/body&gt;\r\n&lt;/html&gt;\r\n</pre>\r\n\r\n<ul>\r\n 	<li><strong>Cabeçalho</strong>: Contém as configurações básicas e a inclusão do arquivo CSS.</li>\r\n 	<li><strong>Corpo</strong>: Inclui o contêiner principal do jogo, o tabuleiro (<code>#tetris</code>), a exibição da pontuação e os botões de controle.</li>\r\n</ul>\r\n<h3>2. styles.css</h3>\r\nEste arquivo contém os estilos do jogo.\r\n<div>\r\n<div>\r\n\r\n\r\n<pre>body {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    height: 100vh;\r\n    background-color: #e0e0e0;\r\n    font-family: Arial, sans-serif;\r\n    margin: 0;\r\n}\r\n\r\n#tetris-container {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n}\r\n\r\n#tetris {\r\n    width: 300px;\r\n    height: 600px;\r\n    border: 2px solid #333;\r\n    background-color: #fff;\r\n    display: grid;\r\n    grid-template-columns: repeat(10, 1fr);\r\n    grid-template-rows: repeat(20, 1fr);\r\n    gap: 1px;\r\n    margin-bottom: 20px;\r\n}\r\n\r\n#tetris div {\r\n    background-color: #f0f0f0;\r\n    box-sizing: border-box;\r\n}\r\n\r\n#score {\r\n    font-size: 1.5em;\r\n    color: #333;\r\n    margin-bottom: 10px;\r\n}\r\n\r\n#score span {\r\n    font-weight: bold;\r\n}\r\n\r\n.buttons {\r\n    display: flex;\r\n    gap: 10px;\r\n}\r\n\r\nbutton {\r\n    padding: 10px 20px;\r\n    font-size: 1em;\r\n    color: #fff;\r\n    background-color: #007bff;\r\n    border: none;\r\n    border-radius: 5px;\r\n    cursor: pointer;\r\n    transition: background-color 0.3s;\r\n}\r\n\r\nbutton:hover {\r\n    background-color: #0056b3;\r\n}\r\n</pre>\r\n\r\n\r\n</div>\r\n</div>\r\n<div>\r\n<ul>\r\n 	<li><strong>Estilos Básicos</strong>: Define o layout da página e do contêiner do jogo.</li>\r\n 	<li><strong>Tabuleiro</strong>: Configura o tamanho e o estilo do tabuleiro de Tetris.</li>\r\n 	<li><strong>Botões</strong>: Estiliza os botões de controle com cores e transições.</li>\r\n</ul>\r\n<h3>3. script.js</h3>\r\nEste arquivo contém a lógica do jogo de Tetris.\r\n\r\n\r\n<pre>document.addEventListener(\'DOMContentLoaded\', () =&gt; {\r\n    const grid = document.querySelector(\'#tetris\');\r\n    const width = 10;\r\n    let timerId;\r\n    let score = 0;\r\n    const colors = [\'orange\', \'red\', \'purple\', \'green\', \'blue\'];\r\n\r\n    // Criar a grade e preencher com divs\r\n    function createBoard() {\r\n        for (let i = 0; i &lt; 200; i++) { // 200 divs para o tabuleiro\r\n            let square = document.createElement(\'div\');\r\n            grid.appendChild(square);\r\n        }\r\n        for (let i = 0; i &lt; 10; i++) { // 10 divs para a linha de base\r\n            let square = document.createElement(\'div\');\r\n            square.classList.add(\'taken\');\r\n            grid.appendChild(square);\r\n        }\r\n    }\r\n    createBoard();\r\n\r\n    let squares = Array.from(grid.querySelectorAll(\'div\'));\r\n    const scoreDisplay = document.querySelector(\'#score span\');\r\n    let nextRandom = 0; // inicialização correta de nextRandom\r\n\r\n    // Os Tetrominos e suas rotações\r\n    const lTetromino = [\r\n        [1, width+1, width*2+1, 2],\r\n        [width, width+1, width+2, width*2+2],\r\n        [1, width+1, width*2+1, width*2],\r\n        [width, width*2, width*2+1, width*2+2]\r\n    ];\r\n\r\n    const zTetromino = [\r\n        [0, width, width+1, width*2+1],\r\n        [width+1, width+2, width*2, width*2+1],\r\n        [0, width, width+1, width*2+1],\r\n        [width+1, width+2, width*2, width*2+1]\r\n    ];\r\n\r\n    const tTetromino = [\r\n        [1, width, width+1, width+2],\r\n        [1, width+1, width+2, width*2+1],\r\n        [width, width+1, width+2, width*2+1],\r\n        [1, width, width+1, width*2+1]\r\n    ];\r\n\r\n    const oTetromino = [\r\n        [0, 1, width, width+1],\r\n        [0, 1, width, width+1],\r\n        [0, 1, width, width+1],\r\n        [0, 1, width, width+1]\r\n    ];\r\n\r\n    const iTetromino = [\r\n        [1, width+1, width*2+1, width*3+1],\r\n        [width, width+1, width+2, width+3],\r\n        [1, width+1, width*2+1, width*3+1],\r\n        [width, width+1, width+2, width+3]\r\n    ];\r\n\r\n    const theTetrominos = [lTetromino, zTetromino, tTetromino, oTetromino, iTetromino];\r\n\r\n    let currentPosition = 4;\r\n    let currentRotation = 0;\r\n    let random = Math.floor(Math.random() * theTetrominos.length);\r\n    let current = theTetrominos[random][currentRotation];\r\n\r\n    // Desenhar o Tetromino\r\n    function draw() {\r\n        current.forEach(index =&gt; {\r\n            squares[currentPosition + index].style.backgroundColor = colors[random];\r\n        });\r\n    }\r\n\r\n    // Desfazer o desenho do Tetromino\r\n    function undraw() {\r\n        current.forEach(index =&gt; {\r\n            squares[currentPosition + index].style.backgroundColor = \'\';\r\n        });\r\n    }\r\n\r\n    // Fazer o Tetromino cair a cada segundo\r\n    timerId = setInterval(moveDown, 1000);\r\n\r\n    // Mover Tetromino para baixo\r\n    function moveDown() {\r\n        undraw();\r\n        currentPosition += width;\r\n        draw();\r\n        freeze();\r\n    }\r\n\r\n    // Congelar quando o Tetromino atinge o fundo da grade\r\n    function freeze() {\r\n        if (current.some(index =&gt; squares[currentPosition + index + width].classList.contains(\'taken\'))) {\r\n            current.forEach(index =&gt; squares[currentPosition + index].classList.add(\'taken\'));\r\n            random = nextRandom;\r\n            nextRandom = Math.floor(Math.random() * theTetrominos.length);\r\n            current = theTetrominos[random][currentRotation];\r\n            currentPosition = 4;\r\n            draw();\r\n            addScore();\r\n            gameOver();\r\n        }\r\n    }\r\n\r\n    // Adicionar pontuação\r\n    function addScore() {\r\n        for (let i = 0; i &lt; 199; i += width) {\r\n            const row = [i, i+1, i+2, i+3, i+4, i+5, i+6, i+7, i+8, i+9];\r\n\r\n            if (row.every(index =&gt; squares[index].classList.contains(\'taken\'))) {\r\n                score += 10;\r\n                scoreDisplay.innerText = score;\r\n                row.forEach(index =&gt; {\r\n                    squares[index].classList.remove(\'taken\');\r\n                    squares[index].style.backgroundColor = \'\';\r\n                });\r\n                const squaresRemoved = squares.splice(i, width);\r\n                squares = squaresRemoved.concat(squares);\r\n                squares.forEach(cell =&gt; grid.appendChild(cell));\r\n            }\r\n        }\r\n    }\r\n\r\n    // Verificar o fim do jogo\r\n    function gameOver() {\r\n        if (current.some(index =&gt; squares[currentPosition + index].classList.contains(\'taken\'))) {\r\n            scoreDisplay.innerText = \'Fim de jogo\';\r\n            clearInterval(timerId);\r\n        }\r\n    }\r\n\r\n    document.addEventListener(\'keyup\', control);\r\n    function control(e) {\r\n        if (e.keyCode === 37) {\r\n            moveLeft();\r\n        } else if (e.keyCode === 38) {\r\n            rotate();\r\n        } else if (e.keyCode === 39) {\r\n            moveRight();\r\n        } else if (e.keyCode === 40) {\r\n            moveDown();\r\n        }\r\n    }\r\n\r\n    function moveLeft() {\r\n        undraw();\r\n        const isAtLeftEdge = current.some(index =&gt; (currentPosition + index) % width === 0);\r\n        if (!isAtLeftEdge) currentPosition -= 1;\r\n        if (current.some(index =&gt; squares[currentPosition + index].classList.contains(\'taken\'))) {\r\n            currentPosition += 1;\r\n        }\r\n        draw();\r\n    }\r\n\r\n    function moveRight() {\r\n        undraw();\r\n        const isAtRightEdge = current.some(index =&gt; (currentPosition + index) % width === width - 1);\r\n        if (!isAtRightEdge) currentPosition += 1;\r\n        if (current.some(index =&gt; squares[currentPosition + index].classList.contains(\'taken\'))) {\r\n            currentPosition -= 1;\r\n        }\r\n        draw();\r\n    }\r\n\r\n    function rotate() {\r\n        undraw();\r\n        currentRotation++;\r\n        if (currentRotation === current.length) {\r\n            currentRotation = 0;\r\n        }\r\n        current = theTetrominos[random][currentRotation];\r\n        draw();\r\n    }\r\n\r\n    document.querySelector(\'#restart\').addEventListener(\'click\', () =&gt; {\r\n        clearInterval(timerId);\r\n        score = 0;\r\n        scoreDisplay.innerText = score;\r\n        nextRandom = 0;\r\n        createBoard();\r\n        random = Math.floor(Math.random() * theTetrominos.length);\r\n        current = theTetrominos[random][currentRotation];\r\n        currentPosition = 4;\r\n        draw();\r\n        timerId = setInterval(moveDown, 1000);\r\n    });\r\n\r\n    document.querySelector(\'#pause\').addEventListener(\'click\', () =&gt; {\r\n        if (timerId) {\r\n            clearInterval(timerId);\r\n            timerId = null;\r\n            document.querySelector(\'#pause\').innerText = \'Retomar\';\r\n        } else {\r\n            timerId = setInterval(moveDown, 1000);\r\n            document.querySelector(\'#pause\').innerText = \'Pausar\';\r\n        }\r\n    });\r\n\r\n    document.querySelector(\'#reset-score\').addEventListener(\'click\', () =&gt; {\r\n        score = 0;\r\n        scoreDisplay.innerText = score;\r\n    });\r\n});\r\n</pre>\r\n\r\n<ul>\r\n 	<li><strong>Variáveis e Seletores</strong>: Definem elementos do DOM e variáveis necessárias para o jogo.</li>\r\n 	<li><strong>createBoard()</strong>: Cria o tabuleiro do jogo preenchendo-o com células.</li>\r\n 	<li><strong>Tetrominos</strong>: Define as formas e rotações dos Tetrominos.</li>\r\n 	<li><strong>Desenho e Movimentação</strong>: Funções para desenhar, mover, rotacionar e congelar os Tetrominos.</li>\r\n 	<li><strong>Controle de Teclado</strong>: Adiciona eventos de teclado para mover e rotacionar os Tetrominos.</li>\r\n 	<li><strong>Funções de Controle</strong>: Funções para reiniciar, pausar e zerar a pontuação do jogo.</li>\r\n</ul>\r\n<h2>Como Executar</h2>\r\n<ol>\r\n 	<li>Faça o download ou clone este repositório.</li>\r\n 	<li>Abra o arquivo <code>index.html</code> em um navegador web.</li>\r\n 	<li>O jogo será carregado e estará pronto para jogar.</li>\r\n 	<li>Utilize as teclas de seta para mover e rotacionar os Tetrominos:\r\n<ul>\r\n 	<li>Seta para esquerda: Move o Tetromino para a esquerda.</li>\r\n 	<li>Seta para direita: Move o Tetromino para a direita.</li>\r\n 	<li>Seta para cima: Rotaciona o Tetromino.</li>\r\n 	<li>Seta para baixo: Move o Tetromino para baixo.</li>\r\n</ul>\r\n</li>\r\n 	<li>Use os botões de controle para reiniciar, pausar e zerar a pontuação do jogo.</li>\r\n</ol>\r\n</div>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-06-02 11:29:25', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
