INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Definindo o Ano Atual como Valor Padrão em Migrations do Laravel', 'definindo-o-ano-atual-como-valor-padrao-em-migrations-do-laravel', 'Ao trabalhar com migrations no Laravel, uma tarefa comum é definir valores padrão para colunas em tabelas de banco de dados. Uma situação específica é definir o ano atual como valor padrão para uma coluna. Este tutorial…', 'Ao trabalhar com migrations no Laravel, uma tarefa comum é definir valores padrão para colunas em tabelas de banco de dados. Uma situação específica é definir o ano atual como valor padrão para uma coluna. Este tutorial mostrará como fazer isso de maneira uniforme, independente do banco de dados escolhido, com exemplos específicos para MySQL e PostgreSQL.\r\n<h3>Passo 1: Criar a Migration</h3>\r\nPrimeiro, crie a migration para adicionar a coluna <code>ano</code> à sua tabela. Use o comando Artisan para gerar a migration:\r\n\r\n\r\n<pre>php artisan make:migration add_ano_to_exemplos_table --table=exemplos\r\n</pre>\r\n\r\n\r\nNo arquivo de migration gerado, adicione a coluna <code>ano</code> com o valor padrão apropriado, dependendo do banco de dados:\r\n<h3>Exemplo para MYSQL:</h3>\r\n\r\n<pre>public function up()\r\n{\r\n    Schema::table(\'exemplos\', function (Blueprint $table) {\r\n        $table-&gt;integer(\'ano\')-&gt;nullable()-&gt;default(DB::raw(\'YEAR(CURDATE())\'));\r\n    });\r\n}\r\n\r\npublic function down()\r\n{\r\n    Schema::table(\'exemplos\', function (Blueprint $table) {\r\n        $table-&gt;dropColumn(\'ano\');\r\n    });\r\n}\r\n</pre>\r\n\r\n<h3>Exemplo para POSTGRESQL:</h3>\r\n\r\n<pre>public function up()\r\n{\r\n    Schema::table(\'exemplos\', function (Blueprint $table) {\r\n        $table-&gt;integer(\'ano\')-&gt;nullable()-&gt;default(DB::raw(\'EXTRACT(YEAR FROM CURRENT_DATE)\'));\r\n    });\r\n}\r\n\r\npublic function down()\r\n{\r\n    Schema::table(\'exemplos\', function (Blueprint $table) {\r\n        $table-&gt;dropColumn(\'ano\');\r\n    });\r\n}\r\n</pre>\r\n\r\n<h3>Exemplo de como definir diretamento no modelo:</h3>\r\n\r\n<pre>namespace App\\Models;\r\n\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n\r\nclass Exemplo extends Model\r\n{\r\n    protected static function boot()\r\n    {\r\n        parent::boot();\r\n\r\n        static::creating(function ($model) {\r\n            if (is_null($model-&gt;ano)) {\r\n                $model-&gt;ano = date(\'Y\');\r\n            }\r\n        });\r\n    }\r\n}\r\n</pre>\r\n\r\n\r\nDepois de realizado os passos acima execute as migrations\r\n\r\n\r\n<pre>php artisan migrate\r\n</pre>\r\n\r\n\r\nPara garantir que tudo está funcionando conforme o esperado, você pode testar criando um novo registro na tabela <code>exemplos</code>. No Tinker ou em um controlador, crie um novo registro sem especificar o valor da coluna <code>ano</code>:\r\n\r\n\r\n<pre>use App\\Models\\Exemplo;\r\n\r\n$newRecord = Exemplo::create([\r\n    \'status\' =&gt; \'AGUARDANDO\'\r\n]);\r\n\r\necho $newRecord-&gt;ano; // Deve exibir o ano atual\r\n</pre>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-06-03 17:04:19', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
