INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como Instalar o PostgreSQL 16 no Linux Mint 21', 'como-instalar-o-postgresql-16-no-linux-mint-21', 'O PostgreSQL 16 ainda não está disponível nos repositórios oficiais do Linux Mint 21, então usaremos o repositório oficial do PostgreSQL. O repositório da versão \"Jammy\" é compatível com o Linux Mint 21. Para seguir com…', 'O PostgreSQL 16 ainda não está disponível nos repositórios oficiais do Linux Mint 21, então usaremos o repositório oficial do PostgreSQL. O repositório da versão \"Jammy\" é compatível com o Linux Mint 21.\r\n\r\nPara seguir com a instalação do POSTGRES 16 no Linux mint 21 Vera siga os passos abaixo:\r\n\r\n\r\n<pre>-- Crie uma configuração de repositório:\r\nsudo sh -c \'echo \"deb http://apt.postgresql.org/pub/repos/apt jammy-pgdg main\" &gt; /etc/apt/sources.list.d/pgdg.list\'\r\n\r\n-- Importe a chave do repositório:\r\nwget --quiet -O - https://www.postgresql.org/media/keys/ACCC4CF8.asc | sudo apt-key add -\r\n\r\n-- Atualize os pacotes e o sistema:\r\nsudo apt update &amp;&amp; sudo apt upgrade -y\r\n\r\n-- Instale o PostgreSQL:\r\nsudo apt install postgresql -y\r\n\r\n-- Verifique o status:\r\nservice postgresql status\r\nsudo netstat -tulpn | grep postgres\r\n\r\n</pre>\r\n\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-09-16 18:20:47', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
