INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Instalação e Configuração do OpenSSH no Ubuntu', 'instalacao-e-configuracao-do-openssh-no-ubuntu', 'Este tutorial rápido e objetivo vai te mostrar como instalar e configurar o OpenSSH no Ubuntu, além de incluir algumas dicas extras de configuração de segurança. 1. Atualizar o sistema Abra o terminal e execute o…', 'Este tutorial rápido e objetivo vai te mostrar como instalar e configurar o OpenSSH no Ubuntu, além de incluir algumas dicas extras de configuração de segurança.\r\n<h2>1. Atualizar o sistema</h2>\r\nAbra o terminal e execute o comando para garantir que todos os pacotes estão atualizados:\r\n<pre><code>sudo apt update &amp;&amp; sudo apt upgrade -y</code></pre>\r\n<h2>2. Instalar o OpenSSH</h2>\r\nInstale o servidor OpenSSH com o seguinte comando:\r\n<pre><code>sudo apt install openssh-server -y</code></pre>\r\n<h2>3. Iniciar o serviço OpenSSH</h2>\r\nApós a instalação, inicie o serviço e configure-o para iniciar automaticamente com o sistema:\r\n<pre><code>sudo systemctl enable --now ssh</code></pre>\r\nVerifique se o serviço está rodando corretamente com:\r\n<pre><code>sudo systemctl status ssh</code></pre>\r\n<h2>4. Configurar o firewall</h2>\r\nCertifique-se de que o firewall (UFW) está configurado para permitir conexões SSH. Verifique o status do firewall com:\r\n<pre><code>sudo ufw status</code></pre>\r\nSe necessário, permita o tráfego SSH:\r\n<pre><code>sudo ufw allow ssh</code></pre>\r\n<h2>5. Conectar-se ao servidor</h2>\r\nAgora você pode se conectar ao servidor usando o comando SSH. Substitua <code>username</code> pelo seu nome de usuário e <code>IP_address</code> pelo IP do servidor:\r\n<pre><code>ssh username@IP_address</code></pre>\r\n<h2>6. Melhorar a segurança do SSH (Opcional)</h2>\r\nPara aumentar a segurança da sua conexão SSH, você pode alterar algumas configurações no arquivo <code>/etc/ssh/sshd_config</code>. Aqui estão algumas sugestões:\r\n<ul>\r\n 	<li>\r\n<ul>\r\n 	<li>Mudar a porta SSH para um valor mais seguro (ex: 49532):</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<pre><code>Port 49532</code></pre>\r\n<ul>\r\n 	<li>\r\n<ul>\r\n 	<li>Desabilitar login de root:</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<pre><code>PermitRootLogin no</code></pre>\r\n<ul>\r\n 	<li>\r\n<ul>\r\n 	<li>Usar autenticação por chave em vez de senha:</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<pre><code>PubkeyAuthentication yes</code></pre>\r\n<ul>\r\n 	<li>\r\n<ul>\r\n 	<li>Restringir o número de tentativas de autenticação:</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<pre><code>MaxAuthTries 3</code></pre>\r\nApós realizar essas alterações, reinicie o serviço SSH:\r\n<pre><code>sudo systemctl restart ssh</code></pre>\r\nPronto! O OpenSSH está instalado e configurado no seu Ubuntu com as melhores práticas de segurança.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-09-30 08:40:49', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
