INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Um resumo sobre o WSL2', 'um-resumo-sobre-o-wsl2', 'O WSL 2 (Windows Subsystem for Linux) representa um grande avanço na integração entre o Windows e o Linux, permitindo que desenvolvedores tenham acesso a um ambiente Linux completo dentro do Windows. Com melhorias de…', 'O <strong>WSL 2 (Windows Subsystem for Linux)</strong> representa um grande avanço na integração entre o Windows e o Linux, permitindo que desenvolvedores tenham acesso a um ambiente Linux completo dentro do Windows. Com melhorias de performance em comparação ao WSL 1, o WSL 2 utiliza um kernel Linux real, oferecendo total compatibilidade com system calls e proporcionando uma experiência mais fluida. Ferramentas como Docker e Visual Studio Code já podem ser usadas no WSL 2, facilitando a vida de desenvolvedores que necessitam trabalhar com múltiplos ambientes.\r\n<h3>Principais benefícios do WSL 2:</h3>\r\n<ul>\r\n 	<li><strong>Melhoria de performance</strong>: Operações de E/S (entrada/saída) mais rápidas.</li>\r\n 	<li><strong>Compatibilidade completa</strong>: Adoção de um kernel Linux real traz suporte total às chamadas de sistema.</li>\r\n 	<li><strong>Integração com ferramentas populares</strong>: Docker, VS Code e outras ferramentas amplamente utilizadas por desenvolvedores funcionam perfeitamente com o WSL 2.</li>\r\n 	<li><strong>Facilidade de instalação</strong>: O processo de instalação é intuitivo e similar ao do WSL 1.</li>\r\n</ul>\r\n<h3>Como isso impacta os desenvolvedores?</h3>\r\nO WSL 2 oferece o melhor dos dois mundos: a familiaridade do ambiente Windows com o poder e a flexibilidade do Linux. Essa integração permite que os desenvolvedores trabalhem de maneira mais produtiva, sem precisar configurar máquinas virtuais ou sistemas dual-boot. O WSL 2 é uma ferramenta poderosa para quem precisa de um ambiente de desenvolvimento Linux, mas prefere continuar usando o Windows como sistema principal.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-10-03 08:21:41', 'published', NULL)
