INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como Redimensionar Imagens Base64 com JavaScript e TypeScript', 'como-redimensionar-imagens-base64-com-javascript-e-typescript', 'Ao trabalhar com imagens base64 no front-end, é comum precisar redimensioná-las para melhorar o desempenho da aplicação, especialmente ao enviá-las para servidores ou APIs. Neste artigo, vamos explorar como…', 'Ao trabalhar com imagens base64 no front-end, é comum precisar redimensioná-las para melhorar o desempenho da aplicação, especialmente ao enviá-las para servidores ou APIs. Neste artigo, vamos explorar como redimensionar imagens base64 com JavaScript, garantindo que sua largura não exceda 150px. A solução é desenvolvida em TypeScript para garantir maior segurança e clareza no código.\r\n<h3>Por que Redimensionar Imagens?</h3>\r\nImagens grandes em base64 podem impactar a performance de carregamento, principalmente em dispositivos móveis com conexões limitadas. Redimensionar essas imagens reduz o tamanho dos dados enviados, resultando em uma melhor experiência do usuário.\r\n<h3>Passo a Passo para Redimensionar Imagens Base64</h3>\r\n<h4>Função JavaScript Simples</h4>\r\nO código abaixo é uma função simples em JavaScript que redimensiona uma imagem base64 para uma largura máxima de 150px:\r\n\r\n\r\n<pre>function resizeBase64Image(base64Image: string): Promise&lt;string&gt; {\r\n  return new Promise((resolve, reject) =&gt; {\r\n    const img = new Image();\r\n    img.src = base64Image;\r\n\r\n    img.onload = () =&gt; {\r\n      const canvas = document.createElement(\'canvas\');\r\n      let width = img.width;\r\n      let height = img.height;\r\n\r\n      // Limita a largura para no máximo 150px\r\n      if (width &gt; 150) {\r\n        height = (height * 150) / width;\r\n        width = 150;\r\n      }\r\n\r\n      canvas.width = width;\r\n      canvas.height = height;\r\n      const ctx = canvas.getContext(\'2d\');\r\n      if (ctx) {\r\n        ctx.drawImage(img, 0, 0, width, height);\r\n        const resizedBase64 = canvas.toDataURL(\'image/jpeg\');\r\n        resolve(resizedBase64);\r\n      } else {\r\n        reject(new Error(\"Erro ao obter contexto 2D\"));\r\n      }\r\n    };\r\n\r\n    img.onerror = (err) =&gt; {\r\n      console.error(\"Erro ao carregar a imagem: \", err);\r\n      resolve(\'/sem_anexo.png\'); // Retorna a URL de fallback em caso de erro\r\n    };\r\n  });\r\n}\r\n</pre>\r\n\r\n<h3>Entendendo a Função</h3>\r\n<ol>\r\n 	<li><strong>Imagem Base64 como Input:</strong> A função recebe uma string base64 representando a imagem.</li>\r\n 	<li><strong>Objeto <code>Image</code>:</strong> Criamos um novo objeto <code>Image</code> para carregar a imagem base64.</li>\r\n 	<li><strong>Redimensionamento:</strong> Se a largura da imagem for maior que 150px, ela é redimensionada proporcionalmente. O objetivo é preservar a proporção da imagem original.</li>\r\n 	<li><strong>Canvas:</strong> Utilizamos o canvas para redesenhar a imagem com o novo tamanho, convertendo o resultado de volta para base64.</li>\r\n 	<li><strong>Tratamento de Erros:</strong> Em caso de erro, como falha ao carregar a imagem, o código retorna uma URL de fallback (<code>\'/sem_anexo.png\'</code>).</li>\r\n</ol>\r\n<h3>Benefícios de Usar TypeScript</h3>\r\nO TypeScript garante que tipos corretos sejam usados em todos os pontos do código. Isso evita erros de execução ao garantir que estamos sempre manipulando os tipos corretos, como strings ou objetos de imagem. Além disso, o uso de promessas facilita o manuseio assíncrono.\r\n<h3>Conclusão</h3>\r\nRedimensionar imagens em base64 usando JavaScript ou TypeScript é uma tarefa simples, mas essencial para melhorar a performance de aplicações que trabalham com uploads de imagens. Este exemplo mostra como você pode adaptar o tamanho da imagem com facilidade e robustez.\r\n\r\nPara mais detalhes, você pode conferir o artigo <a href=\"https://kutia.net/resizing-base64-images-with-javascript-a-snap-to-scale/\" target=\"_new\" rel=\"noopener\">Resizing Base64 Images with JavaScript</a>, que inspirou essa solução.', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-10-15 07:57:13', 'published', NULL)
