INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Design Pattern Facade em PHP : Exemplo prático', 'design-pattern-facade-em-php-exemplo-pratico', 'O Design Pattern Facade é uma solução elegante para simplificar a interface de um subsistema complexo, tornando-o mais fácil de usar. Ele atua como uma fachada que esconde a complexidade de classes e interações…', 'O <strong>Design Pattern Facade</strong> é uma solução elegante para simplificar a interface de um subsistema complexo, tornando-o mais fácil de usar. Ele atua como uma fachada que esconde a complexidade de classes e interações internas, oferecendo uma interface simplificada para o cliente. Vamos explorar este padrão em PHP com exemplos práticos e sem a necessidade de bibliotecas externas.\r\n<h3>Quando Usar o Facade?</h3>\r\n<ul>\r\n 	<li>Quando você deseja oferecer uma interface simplificada para um sistema complexo.</li>\r\n 	<li>Quando várias classes e objetos precisam ser utilizados em conjunto, mas você quer minimizar o acoplamento do cliente a essas classes.</li>\r\n 	<li>Quando é necessário reduzir a complexidade das interações entre componentes.</li>\r\n</ul>\r\n<h3>Exemplo: Sistema de Pedidos</h3>\r\nImagine que estamos desenvolvendo um sistema de pedidos online. Ele envolve diferentes partes: processamento de pagamento, estoque e envio. Sem o Facade, o cliente precisaria interagir diretamente com cada uma dessas partes.\r\n\r\nVamos criar um exemplo de como seria sem o Facade, e depois aplicaremos o padrão para simplificar a interação.\r\n<h4>Sem Facade:</h4>\r\n\r\n<pre>class Estoque {\r\n    public function diminuirEstoque($produtoId, $quantidade) {\r\n        echo \"Estoque reduzido para o produto $produtoId em $quantidade unidades.\\n\";\r\n    }\r\n}\r\n\r\nclass Pagamento {\r\n    public function processarPagamento($valor) {\r\n        echo \"Pagamento de R$$valor processado com sucesso.\\n\";\r\n    }\r\n}\r\n\r\nclass Envio {\r\n    public function enviarProduto($produtoId) {\r\n        echo \"Produto $produtoId enviado.\\n\";\r\n    }\r\n}\r\n\r\n// Cliente precisando lidar com tudo\r\n$estoque = new Estoque();\r\n$pagamento = new Pagamento();\r\n$envio = new Envio();\r\n\r\n// Fluxo de pedido\r\n$estoque-&gt;diminuirEstoque(101, 2);\r\n$pagamento-&gt;processarPagamento(150);\r\n$envio-&gt;enviarProduto(101);\r\n</pre>\r\n\r\n\r\nNeste exemplo, o cliente precisa conhecer e interagir diretamente com as classes <code>Estoque</code>, <code>Pagamento</code> e <code>Envio</code>, o que pode tornar o código difícil de gerenciar à medida que o sistema cresce.\r\n<h4>Com Facade</h4>\r\nAgora, vamos criar uma classe <code>PedidoFacade</code> para simplificar a interação.\r\n\r\n\r\n<pre>class PedidoFacade {\r\n    protected $estoque;\r\n    protected $pagamento;\r\n    protected $envio;\r\n\r\n    public function __construct() {\r\n        $this-&gt;estoque = new Estoque();\r\n        $this-&gt;pagamento = new Pagamento();\r\n        $this-&gt;envio = new Envio();\r\n    }\r\n\r\n    public function processarPedido($produtoId, $quantidade, $valor) {\r\n        $this-&gt;estoque-&gt;diminuirEstoque($produtoId, $quantidade);\r\n        $this-&gt;pagamento-&gt;processarPagamento($valor);\r\n        $this-&gt;envio-&gt;enviarProduto($produtoId);\r\n    }\r\n}\r\n\r\n// Cliente agora só interage com o Facade\r\n$pedidoFacade = new PedidoFacade();\r\n$pedidoFacade-&gt;processarPedido(101, 2, 150);\r\n</pre>\r\n\r\n\r\nAgora, o cliente precisa interagir apenas com o <code>PedidoFacade</code>, que esconde a complexidade do sistema. Isso torna o código mais limpo e fácil de manter.\r\n<h3>Explicação</h3>\r\n<ol>\r\n 	<li><strong>Facade (<code>PedidoFacade</code>)</strong>: A classe <code>PedidoFacade</code> age como uma \"fachada\" para o subsistema de pedidos. Ela conhece os objetos internos (<code>Estoque</code>, <code>Pagamento</code>, <code>Envio</code>), mas o cliente não precisa se preocupar com eles.</li>\r\n 	<li><strong>Subsistema</strong>: As classes <code>Estoque</code>, <code>Pagamento</code> e <code>Envio</code> formam o subsistema que executa o trabalho real. Elas permanecem desacopladas e focadas em suas responsabilidades específicas.</li>\r\n</ol>\r\n<h3>Vantagens do Facade</h3>\r\n<ul>\r\n 	<li><strong>Simplicidade</strong>: O cliente interage com uma interface simplificada e não precisa se preocupar com a implementação dos componentes.</li>\r\n 	<li><strong>Desacoplamento</strong>: O cliente não depende diretamente de várias classes. Mudanças internas no subsistema não afetam a interface exposta pelo <code>Facade</code>.</li>\r\n 	<li><strong>Manutenção</strong>: O código se torna mais fácil de manter, já que a complexidade interna fica encapsulada.</li>\r\n</ul>\r\nO padrão <strong>Facade</strong> é uma maneira eficaz de ocultar a complexidade de sistemas com múltiplas classes e responsabilidades, simplificando a interação para o cliente. Neste exemplo em PHP, criamos um sistema de pedidos onde o cliente interage com uma única classe (<code>PedidoFacade</code>), deixando todo o trabalho pesado para o subsistema. Este padrão ajuda a manter o código mais organizado e mais fácil de manter, especialmente em sistemas complexos.\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-10-16 08:28:07', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
