INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Tutorial: Exportando Imagens Base64 Usando Laravel Excel', 'tutorial-exportando-lista-de-clientes-com-imagens-base64-usando-laravel-excel', 'Neste tutorial, vamos aprender como exportar uma lista de cadastros de clientes para uma planilha Excel, incluindo as fotos dos clientes que estão armazenadas como strings base64. Usaremos o pacote Laravel Excel para…', 'Neste tutorial, vamos aprender como exportar uma lista de cadastros de clientes para uma planilha Excel, incluindo as fotos dos clientes que estão armazenadas como strings base64. Usaremos o pacote <strong>Laravel Excel</strong> para realizar essa exportação, integrando dados e imagens de forma eficaz.\r\n<h3>1. Instalação do Laravel Excel</h3>\r\nPrimeiro, certifique-se de que o pacote Laravel Excel está instalado no seu projeto. Se ainda não o instalou, você pode fazer isso com o seguinte comando:\r\n\r\n\r\n<pre>composer require maatwebsite/excel</pre>\r\n\r\n\r\nMais informações sobre a instalação do Laravel excel consulte :<a href=\"https://docs.laravel-excel.com/3.1/getting-started/installation.html\"> https://docs.laravel-excel.com/3.1/getting-started/installation.html</a>\r\n<h3>2. Criando a Exportação de Clientes</h3>\r\nAgora, vamos criar a classe de exportação. Esta classe será responsável por organizar os dados da lista de clientes e adicionar as imagens correspondentes de cada cliente.\r\n\r\n\r\n<pre>&lt;?php\r\n\r\nnamespace App\\Exports;\r\n\r\nuse Maatwebsite\\Excel\\Concerns\\FromArray;\r\nuse Maatwebsite\\Excel\\Concerns\\WithHeadings;\r\nuse Maatwebsite\\Excel\\Concerns\\WithDrawings;\r\nuse PhpOffice\\PhpSpreadsheet\\Worksheet\\MemoryDrawing;\r\n\r\nclass ClientesExport implements FromArray, WithHeadings, WithDrawings\r\n{\r\n    protected $clientes;\r\n    protected $drawings = [];\r\n\r\n    public function __construct($clientes)\r\n    {\r\n        $this-&gt;clientes = $clientes;\r\n    }\r\n\r\n    // Função para montar os dados em array\r\n    public function array(): array\r\n    {\r\n        $data = [];\r\n\r\n        foreach ($this-&gt;clientes as $cliente) {\r\n            $data[] = [\r\n                \'id\' =&gt; $cliente-&gt;id,\r\n                \'nome\' =&gt; $cliente-&gt;nome,\r\n                \'email\' =&gt; $cliente-&gt;email,\r\n                \'foto\' =&gt; \'\' // A imagem será adicionada via `drawings()`\r\n            ];\r\n        }\r\n\r\n        return $data;\r\n    }\r\n\r\n    // Função para definir os cabeçalhos das colunas\r\n    public function headings(): array\r\n    {\r\n        return [\'ID\', \'Nome\', \'Email\', \'Foto\'];\r\n    }\r\n\r\n    // Função que adiciona as imagens na planilha\r\n    public function drawings()\r\n    {\r\n        $drawings = [];\r\n        $rowIndex = 2; // As imagens começam na linha 2, após o cabeçalho.\r\n\r\n        foreach ($this-&gt;clientes as $cliente) {\r\n            if (!empty($cliente-&gt;foto_base64)) {\r\n                // Chama o método para criar o desenho da imagem\r\n                $drawing = $this-&gt;createMemoryDrawing($cliente-&gt;foto_base64, \'D\' . $rowIndex);\r\n                $drawings[] = $drawing;\r\n            }\r\n            $rowIndex++;\r\n        }\r\n\r\n        return $drawings;\r\n    }\r\n\r\n    // Função para criar a imagem a partir da string base64 e ajustá-la proporcionalmente\r\n    private function createMemoryDrawing($base64Image, $coordinates)\r\n    {\r\n        // Cria o recurso de imagem a partir da string base64\r\n        $imageResource = $this-&gt;createImageFromBase64($base64Image);\r\n\r\n        // Obtém as dimensões originais da imagem\r\n        $originalWidth = imagesx($imageResource);\r\n        $originalHeight = imagesy($imageResource);\r\n\r\n        // Define a nova largura (80px) e calcula a altura proporcional\r\n        $newWidth = 80;\r\n        $newHeight = ($originalHeight / $originalWidth) * $newWidth;\r\n\r\n        // Cria a imagem na planilha com as novas dimensões\r\n        $drawing = new MemoryDrawing();\r\n        $drawing-&gt;setImageResource($imageResource);\r\n        $drawing-&gt;setRenderingFunction(MemoryDrawing::RENDERING_PNG);\r\n        $drawing-&gt;setMimeType(MemoryDrawing::MIMETYPE_PNG);\r\n        $drawing-&gt;setCoordinates($coordinates);\r\n        $drawing-&gt;setWidth($newWidth); // Define a largura como 80px\r\n        $drawing-&gt;setHeight($newHeight); // Define a altura proporcional\r\n\r\n        return $drawing;\r\n    }\r\n\r\n    // Função para converter a string base64 em um recurso de imagem\r\n    private function createImageFromBase64($base64Image)\r\n    {\r\n        // Remove a parte \'base64,\' se estiver presente\r\n        if (strpos($base64Image, \'base64,\') !== false) {\r\n            $imageParts = explode(\'base64,\', $base64Image);\r\n            $base64Image = $imageParts[1];\r\n        }\r\n\r\n        // Decodifica a imagem\r\n        $imageData = base64_decode($base64Image);\r\n        $imageResource = imagecreatefromstring($imageData);\r\n\r\n        if (!$imageResource) {\r\n            throw new \\Exception(\'A imagem base64 não pôde ser convertida em um recurso de imagem.\');\r\n        }\r\n\r\n        return $imageResource;\r\n    }\r\n}\r\n</pre>\r\n\r\n<h4>2.1. Criando a Classe <code>ClientesExport</code></h4>\r\nNo terminal, execute o comando:\r\n\r\n\r\n<pre>php artisan make:export ClientesExport --model=Cliente\r\n</pre>\r\n\r\n\r\nDepois, edite o arquivo gerado em <code>app/Exports/ClientesExport.php</code> para incluir as funcionalidades de imagens.\r\n\r\n&nbsp;\r\n<h3>3. Controlador para Exportação</h3>\r\nAgora, vamos criar o controlador para lidar com a exportação de clientes. No terminal, crie o controlador:\r\n\r\n\r\n<pre>php artisan make:controller ClienteController\r\n</pre>\r\n\r\n\r\nNo controlador <code>ClienteController.php</code>, adicione a função para exportar a lista de clientes com imagens:\r\n\r\n\r\n<pre>&lt;?php\r\n\r\nnamespace App\\Http\\Controllers;\r\n\r\nuse App\\Exports\\ClientesExport;\r\nuse App\\Models\\Cliente;\r\nuse Maatwebsite\\Excel\\Facades\\Excel;\r\n\r\nclass ClienteController extends Controller\r\n{\r\n    public function exportarClientes()\r\n    {\r\n        $clientes = Cliente::all(); // Pega todos os clientes do banco\r\n        return Excel::download(new ClientesExport($clientes), \'clientes.xlsx\');\r\n    }\r\n}\r\n</pre>\r\n\r\n<h3>4. Criando as Rotas</h3>\r\nNo arquivo <code>routes/web.php</code>, adicione uma rota para acessar a funcionalidade de exportação:\r\n\r\n\r\n<pre>use App\\Http\\Controllers\\ClienteController;\r\n\r\nRoute::get(\'exportar-clientes\', [ClienteController::class, \'exportarClientes\']);</pre>\r\n\r\n<h3>5. Testando a Exportação</h3>\r\nAgora que tudo está configurado, você pode testar a exportação. Basta acessar a rota <code>http://localhost:8000/exportar-clientes</code> no seu navegador, e a planilha Excel será gerada para download, contendo as fotos dos clientes.\r\n<h3>6. Considerações Finais</h3>\r\n<ul>\r\n 	<li>As imagens são processadas utilizando a classe <code>MemoryDrawing</code>, que converte as imagens base64 para o formato PNG.</li>\r\n 	<li>As coordenadas das imagens são definidas de acordo com a linha correspondente dos dados do cliente.</li>\r\n 	<li>O campo <code>foto_base64</code> na tabela de clientes deve armazenar a imagem codificada em base64. Você pode usar bibliotecas JavaScript para capturar e converter a imagem diretamente no front-end.</li>\r\n</ul>\r\n<h3>Fontes:</h3>\r\n<a href=\"https://docs.laravel-excel.com/3.1/exports/drawings.html\" target=\"_new\" rel=\"noopener\">Laravel Excel Documentation</a>​\r\n<div><a href=\"https://docs.laravel-excel.com/3.1/exports/drawings.html\" target=\"_blank\" rel=\"noopener\"><span>Laravel Excel</span></a></div>\r\n.<a href=\"https://github.com/Maatwebsite/Laravel-Excel/issues/3396\" target=\"_new\" rel=\"noopener\">Laravel Export with Images</a>​\r\n<div><a href=\"https://github.com/SpartnerNL/Laravel-Excel/discussions/3396\" target=\"_blank\" rel=\"noopener\"><span>GitHub</span></a></div>\r\n.<a href=\"https://phpspreadsheet.readthedocs.io/en/latest/topics/recipes/#drawing-images\" target=\"_new\" rel=\"noopener\">PhpSpreadsheet Drawings</a>​\r\n<div><a href=\"https://docs.laravel-excel.com/4.x/exports/exporting.html\" target=\"_blank\" rel=\"noopener\"><span>Laravel Excel</span></a></div>\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2024-10-23 08:42:00', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
