INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Guia de Deploy de Aplicação Laravel com Nginx em uma VPS com Ubuntu e HTTPS em um VPS', 'guia-de-deploy-de-aplicacao-laravel-com-nginx-em-uma-vps-com-ubuntu-e-https-em-um-vps', 'Neste post, você aprenderá a fazer o deploy de uma aplicação Laravel em uma VPS rodando Ubuntu com o servidor web Nginx e configurar HTTPS utilizando o Certbot. Além disso, será abordado como configurar um banco de…', '<p>Neste post, você aprenderá a fazer o deploy de uma aplicação Laravel em uma VPS rodando Ubuntu com o servidor web Nginx e configurar HTTPS utilizando o Certbot. Além disso, será abordado como configurar um banco de dados MySQL na VPS.</p>\r\n    \r\n    <h2>Preparando o Servidor VPS</h2>\r\n    <h3>Atualizando os pacotes do sistema:</h3>\r\n    <pre><code>sudo apt update && sudo apt upgrade -y</code></pre>\r\n\r\n    <h3>Instalando o Nginx:</h3>\r\n    <pre><code>sudo apt install nginx -y</code></pre>\r\n\r\n    <h3>Instalando o PHP e extensões necessárias:</h3>\r\n    <pre><code>\r\nsudo apt install php8.3-cli\r\nsudo apt install php8.3-ctype php8.3-curl php8.3-dom php8.3-fileinfo php8.3-mbstring php8.3-opcache php8.3-pdo php8.3-tokenizer php8.3-xml php8.3-fpm php8.3-mysql php8.3-zip unzip\r\n    </code></pre>\r\n\r\n    <h3>Instalando o Composer:</h3>\r\n    <pre><code>\r\ncd ~\r\ncurl -sS https://getcomposer.org/installer -o /tmp/composer-setup.php\r\nHASH=`curl -sS https://composer.github.io/installer.sig`\r\necho $HASH\r\nphp -r \"if (hash_file(\'SHA384\', \'/tmp/composer-setup.php\') === \'$HASH\') { echo \'Installer verified\'; } else { echo \'Installer corrupt\'; unlink(\'composer-setup.php\'); } echo PHP_EOL;\"\r\nsudo php /tmp/composer-setup.php --install-dir=/usr/local/bin --filename=composer\r\ncomposer\r\n    </code></pre>\r\n\r\n    <h3>Instalando o MySQL:</h3>\r\n    <pre><code>\r\nsudo systemctl enable mysql\r\nsudo systemctl enable nginx\r\nsudo systemctl enable php8.3-fpm\r\n\r\nsudo systemctl status mysql\r\nsudo systemctl status nginx\r\nsudo systemctl status php8.3-fpm\r\n    </code></pre>\r\n\r\n    <h3>Observação</h3>\r\n    <p>Se sua aplicação Laravel utiliza o Node.js e npm, você precisará instalá-los também:</p>\r\n    <pre><code>\r\nsudo apt install nodejs npm -y\r\nnode -v\r\nnpm -v\r\n    </code></pre>\r\n\r\n    <h2>Configurando o Projeto Laravel</h2>\r\n    <h3>Clonando o repositório da aplicação:</h3>\r\n    <pre><code>\r\ncd /var/www\r\nsudo git clone https://github.com/usuario/exemplo.git\r\ncd exemplo\r\n    </code></pre>\r\n\r\n    <h3>Instalando as dependências do Laravel:</h3>\r\n    <pre><code>sudo composer install --optimize-autoloader --no-dev</code></pre>\r\n\r\n    <h3>Copiando o arquivo de exemplo de ambiente:</h3>\r\n    <pre><code>sudo cp .env.example .env</code></pre>\r\n\r\n    <h3>Gerando a chave da aplicação Laravel:</h3>\r\n    <pre><code>sudo php artisan key:generate</code></pre>\r\n\r\n    <h3>Configurando permissões das pastas:</h3>\r\n    <pre><code>\r\nsudo chmod -R 777 storage\r\nsudo chmod -R 777 bootstrap\r\nsudo chmod -R 777 vendor\r\n    </code></pre>\r\n\r\n    <h3>Configurando o Nginx:</h3>\r\n    <h4>Criando um arquivo de configuração:</h4>\r\n    <pre><code>sudo nano /etc/nginx/sites-available/exemplo</code></pre>\r\n\r\n    <h4>Conteúdo do arquivo de configuração:</h4>\r\n    <pre><code>\r\nserver {\r\n    listen 80;\r\n    listen [::]:80;\r\n    server_name example.com;\r\n    root /var/www/example/public;\r\n\r\n    add_header X-Frame-Options \"SAMEORIGIN\";\r\n    add_header X-Content-Type-Options \"nosniff\";\r\n\r\n    index index.php;\r\n\r\n    charset utf-8;\r\n\r\n    location / {\r\n        try_files $uri $uri/ /index.php?$query_string;\r\n    }\r\n\r\n    location = /favicon.ico { access_log off; log_not_found off; }\r\n    location = /robots.txt  { access_log off; log_not_found off; }\r\n\r\n    error_page 404 /index.php;\r\n\r\n    location ~ \\.php$ {\r\n        fastcgi_pass unix:/var/run/php/php8.3-fpm.sock;\r\n        fastcgi_param SCRIPT_FILENAME $realpath_root$fastcgi_script_name;\r\n        include fastcgi_params;\r\n    }\r\n\r\n    location ~ /\\.(?!well-known).* {\r\n        deny all;\r\n    }\r\n}\r\n    </code></pre>\r\n\r\n    <h4>Ativando a configuração do site:</h4>\r\n    <pre><code>sudo ln -s /etc/nginx/sites-available/exemplo /etc/nginx/sites-enabled/</code></pre>\r\n\r\n    <h4>Testando e reiniciando o Nginx:</h4>\r\n    <pre><code>\r\nsudo nginx -t\r\nsudo systemctl restart nginx\r\n    </code></pre>\r\n\r\n    <h2>Configurando o Banco de Dados</h2>\r\n    <h3>Acessando o MySQL:</h3>\r\n    <pre><code>sudo mysql -u root -p</code></pre>\r\n\r\n    <h3>Criando o banco de dados e usuário:</h3>\r\n    <pre><code>\r\nCREATE DATABASE nome_do_banco_de_dados;\r\nCREATE USER \'usuario\'@\'localhost\' IDENTIFIED BY \'senha\';\r\nGRANT ALL PRIVILEGES ON nome_do_banco_de_dados.* TO \'usuario\'@\'localhost\';\r\nFLUSH PRIVILEGES;\r\nEXIT;\r\n    </code></pre>\r\n\r\n    <h2>Executando Migrações</h2>\r\n    <pre><code>\r\ncd /var/www/exemplo\r\nsudo php artisan migrate\r\n    </code></pre>\r\n\r\n    <h2>Configurando HTTPS com Certbot</h2>\r\n    <h3>Instalando Certbot:</h3>\r\n    <pre><code>\r\nsudo apt update\r\nsudo apt install snapd\r\nsudo snap install --classic certbot\r\nsudo ln -s /snap/bin/certbot /usr/bin/certbot\r\n    </code></pre>\r\n\r\n    <h3>Obtenha o certificado SSL:</h3>\r\n    <pre><code>sudo certbot --nginx</code></pre>\r\n\r\n    <h3>Renovando certificados:</h3>\r\n    <pre><code>sudo certbot renew --dry-run</code></pre>\r\n\r\n    <p>Sua aplicação Laravel agora está configurada com HTTPS e pode ser acessada pelo domínio configurado.</p>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-01-03 11:32:17', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
