INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Guia de Deploy de Aplicação Laravel com Apache em uma VPS com Ubuntu e HTTPS', 'guia-de-deploy-de-aplicacao-laravel-com-apache-em-uma-vps-com-ubuntu-e-https', 'Neste guia, você aprenderá a fazer o deploy de uma aplicação Laravel em uma VPS rodando Ubuntu com o servidor web Apache e configurar HTTPS utilizando o Certbot. Além de abordar como configurar um banco de dados MySQL…', 'Neste guia, você aprenderá a fazer o deploy de uma aplicação Laravel em uma VPS rodando Ubuntu com o servidor web Apache e configurar HTTPS utilizando o Certbot. Além de abordar como configurar um banco de dados MySQL na VPS.\r\n<h2>Preparando o Servidor VPS</h2>\r\n<strong>Atualize os pacotes do sistema:</strong>\r\n\r\n<!-- notionvc: 8c195e46-1423-4ee3-bd2e-ee8a753d8a14 -->\r\n\r\n<span>sudo apt update &amp;&amp; sudo apt upgrade -y</span>\r\n\r\n<span>Instalando o Apache:</span><!-- notionvc: edfeaccc-e60f-42a1-9e63-b1049be8ce7f -->\r\n\r\n<span>sudo apt install apache2 -y</span>\r\n\r\n<span>Instalando o PHP e extensões necessárias:</span><!-- notionvc: 232f15e6-ecc8-43de-ba5b-6830181f4a06 -->\r\n\r\n<span>sudo apt install php8.3-cli</span>\r\n<span>sudo apt install php8.3-ctype php8.3-curl php8.3-dom php8.3-fileinfo php8.3-mbstring php8.3-opcache php8.3-pdo php8.3-tokenizer php8.3-xml php8.3-fpm php8.3-mysql php8.3-zip unzip</span>\r\n\r\n<span>Instalando o Composer:</span><!-- notionvc: 2e8cfabf-cb0d-49b4-bd44-6a5b566ba0ab -->\r\n\r\n<span>cd ~</span>\r\n<span>curl -sS https://getcomposer.org/installer -o /tmp/composer-setup.php</span>\r\n<span>HASH=`curl -sS https://composer.github.io/installer.sig`</span>\r\n<span>echo $HASH</span>\r\n<span>php -r \"if (hash_file(\'SHA384\', \'/tmp/composer-setup.php\') === \'$HASH\') { echo \'Installer verified\'; } else { echo \'Installer corrupt\'; unlink(\'composer-setup.php\'); } echo PHP_EOL;\"</span>\r\n<span>sudo php /tmp/composer-setup.php --install-dir=/usr/local/bin --filename=composer</span>\r\n<span>composer</span>\r\n\r\n<span>Instalando o MySQL:</span><!-- notionvc: 92878794-1e64-4d08-9dfc-092fc67e2e91 -->\r\n\r\nsudo apt install mysql-server -y\r\n\r\n<span>Habilitando e Testando Serviços:</span><!-- notionvc: 2807f575-8620-4eec-989c-e37a8d1c749c -->\r\n\r\n<span>sudo systemctl enable mysql</span>\r\n<span>sudo systemctl enable apache2</span>\r\n<span>sudo systemctl enable php8.1-fpm</span>\r\n\r\n<span>sudo systemctl status mysql</span>\r\n<span>sudo systemctl status apache2</span>\r\n<span>sudo systemctl status php8.1-fpm</span>\r\n<h3>Observação</h3>\r\nSe sua aplicação Laravel utiliza o Node.js e npm, você precisará instalá-los também:\r\n\r\n<!-- notionvc: de65fa57-fc1e-4a74-8daa-4332dba30e9c -->\r\n\r\n<span>sudo apt install nodejs npm -y</span>\r\n<span>node -v</span>\r\n<span>npm -v</span>\r\n<h2>Configurando o Projeto Laravel</h2>\r\n<strong>Clonando o repositório da sua aplicação Laravel:</strong>\r\n\r\n<!-- notionvc: 7431c343-28b9-4533-a2c7-18513f893e33 -->\r\n\r\n<span>cd /var/www</span>\r\n<span>sudo git clone &lt;https://github.com/usuario/seu-projeto-laravel.git&gt;</span>\r\n<span>cd seu-projeto-laravel</span>\r\n\r\n<span>Instalando as dependências do Laravel:</span><!-- notionvc: 96dedcb9-4738-490c-a103-6bf266683491 -->\r\n\r\n<span>sudo composer install --optimize-autoloader --no-dev</span>\r\n\r\n<span>Copie o arquivo de exemplo de ambiente:</span><!-- notionvc: c0be2a8d-00dd-49b5-8a44-557ac39d22d5 -->\r\n\r\n<span>sudo cp .env.example .env</span>\r\n\r\n<span>Gerando a chave da aplicação Laravel:</span><!-- notionvc: cba2b17a-a01c-40b4-ba16-a82087ad2856 -->\r\n\r\n<span>sudo php artisan key:generate</span>\r\n\r\n<strong>Configure o arquivo <code>.env</code> com as informações do banco de dados e outras configurações de ambiente necessárias.</strong>\r\n\r\n<strong>Configurando as permissões das pastas de armazenamento e cache:</strong>\r\n\r\n<!-- notionvc: 0bf9c1cb-888f-4c4c-ac44-3401d110ca07 -->\r\n\r\n<span>sudo chmod -R 777 storage</span>\r\n<span>sudo chmod -R 777 bootstrap</span>\r\n<span>sudo chmod -R 777 vendor</span>\r\n<h2>Configurar o Apache</h2>\r\n<strong>Criando um arquivo de configuração para seu site:</strong>\r\n\r\n<!-- notionvc: fb14a327-63b1-49c5-b67a-c5960d2d6036 -->\r\n\r\n<span>sudo nano /etc/apache2/sites-available/seu-projeto-laravel.conf</span>\r\n\r\n<span>Adicione o seguinte conteúdo ao arquivo de configuração:</span><!-- notionvc: 7ac31ee1-3cf7-4135-aef4-bf5a116611a8 -->\r\n\r\n<span>&lt;VirtualHost *:80&gt;</span>\r\n<span>ServerAdmin admin@seu-dominio.com</span>\r\n<span>DocumentRoot /var/www/seu-projeto-laravel/public</span>\r\n<span>ServerName seu-dominio.com</span>\r\n<span>ServerAlias www.seu-dominio.com</span>\r\n\r\n<span>&lt;Directory /var/www/seu-projeto-laravel&gt;</span>\r\n<span>Options Indexes FollowSymLinks</span>\r\n<span>AllowOverride All</span>\r\n<span>Require all granted</span>\r\n<span>&lt;/Directory&gt;</span>\r\n\r\n<span>&lt;Directory /var/www/seu-projeto-laravel/public&gt;</span>\r\n<span>AllowOverride All</span>\r\n<span>Require all granted</span>\r\n<span>&lt;/Directory&gt;</span>\r\n\r\n<span>ErrorLog ${APACHE_LOG_DIR}/seu-projeto-laravel_error.log</span>\r\n<span>CustomLog ${APACHE_LOG_DIR}/seu-projeto-laravel_access.log combined</span>\r\n<span>&lt;/VirtualHost&gt;</span>\r\n\r\n<span>Ativando a configuração do site e os módulos necessários:</span><!-- notionvc: ed0a2ff0-adc6-4edd-a89c-e21e18013497 -->\r\n\r\n<span>sudo a2ensite seu-projeto-laravel.conf</span>\r\n<span>sudo a2enmod rewrite</span>\r\n\r\n<span>Reiniciando o Apache para aplicar as mudanças:</span><!-- notionvc: 5b8c67e1-8b6d-472f-ba0f-be023227a9cd -->\r\n\r\n<span>sudo systemctl restart apache2</span>\r\n<h2>Configurar o Banco de Dados</h2>\r\n<strong>Acessando o MySQL:</strong>\r\n\r\n<!-- notionvc: 6b7ee365-b120-42de-b792-5f87348b99c2 -->\r\n\r\nsudo mysql -u root -p\r\n\r\n<span>Criando o banco de dados e o usuário:</span><!-- notionvc: e99d4533-1db8-40cc-8966-12dc5aacb4a4 -->\r\n\r\n<span>CREATE DATABASE nome_do_banco_de_dados;</span>\r\n<span>CREATE USER \'usuario\'@\'localhost\' IDENTIFIED BY \'senha\';</span>\r\n<span>GRANT ALL PRIVILEGES ON nome_do_banco_de_dados.* TO \'usuario\'@\'localhost\';</span>\r\n<span>FLUSH PRIVILEGES;</span>\r\n<span>EXIT;</span>\r\n\r\n<span>No arquivo </span><span spellcheck=\"false\">.env</span><span>, configure as credenciais do banco de dados que você acabou de criar.</span><!-- notionvc: a86736b2-711d-4eed-8751-085dcfe44eb8 -->\r\n<h2>Executando Migrações</h2>\r\n<strong>Rodando as migrações para criar as tabelas no banco de dados:</strong>\r\n\r\n<!-- notionvc: 4fa1237a-c8ae-45b0-b4bc-5925ff09ef64 -->\r\n\r\n<span>cd /var/www/seu-projeto-laravel</span>\r\n<span>sudo php artisan migrate</span>\r\n<h2>Configurar HTTPS com Certbot</h2>\r\n<strong>Instalando o Certbot e o plugin para Apache:</strong>\r\n\r\n<!-- notionvc: 9bcb8611-ed50-471b-84c1-657fb5901fae --><span>sudo apt update</span>\r\n<span>sudo apt install snapd</span>\r\n<span>sudo snap install --classic certbot</span>\r\n<span>sudo ln -s /snap/bin/certbot /usr/bin/certbot</span>\r\n\r\n<span>Obtenha o certificado SSL para seu domínio:</span><!-- notionvc: cc60609c-cfda-410d-9944-49e680687c62 -->\r\n\r\n<span>sudo certbot --apache</span>\r\n\r\nSiga as instruções interativas para:\r\n<ul>\r\n 	<li>Inserir seu endereço de e-mail</li>\r\n 	<li>Aceitar os termos de serviço</li>\r\n 	<li>Escolher o domínio para o qual você deseja ativar o HTTPS</li>\r\n</ul>\r\n<strong>Renove automaticamente os certificados SSL:</strong>\r\n\r\nO Certbot cuida da renovação automática, mas é bom testar:\r\n\r\n<!-- notionvc: 7b443648-c659-4e91-a21d-03da844af72e -->\r\n\r\n<span>sudo certbot renew --dry-run</span>\r\n<h2>Considerações Finais</h2>\r\nSua aplicação Laravel agora deve estar rodando em sua VPS com Ubuntu usando o Apache e com HTTPS configurado e você pode acessá-lo através do domínio configurado.\r\n\r\n<!-- notionvc: 8f1f8741-6443-486a-b6e6-c38f2e858fb5 -->\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-01-06 09:32:32', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
