INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como Converter Arquivos TXT de UTF-8 para ANSI com PHP', 'como-converter-arquivos-txt-de-utf-8-para-ansi-com-php', 'Quando lidamos com arquivos de texto, a codificação de caracteres é um aspecto fundamental para garantir que os textos sejam exibidos corretamente. No entanto, em muitos casos, especialmente em sistemas legados, pode…', '<p>Quando lidamos com arquivos de texto, a codificação de caracteres é um aspecto fundamental para garantir que os textos sejam exibidos corretamente. No entanto, em muitos casos, especialmente em sistemas legados, pode ser necessário converter arquivos de uma codificação moderna, como UTF-8, para ANSI (ISO-8859-1). Este artigo explica como fazer isso usando PHP, com exemplos práticos.</p>\r\n\r\n<h3>Diferença entre UTF-8 e ANSI</h3>\r\n<ul>\r\n 	<li><strong>UTF-8</strong>: Uma codificação moderna e amplamente usada que suporta uma ampla gama de caracteres, incluindo idiomas com caracteres especiais e emojis. Ela é retrocompatível com ASCII.</li>\r\n 	<li><strong>ANSI (ISO-8859-1)</strong>: Codificação mais antiga e limitada que suporta apenas caracteres latinos e não é compatível com idiomas mais complexos.</li>\r\n</ul>\r\nNo caso de arquivos sem caracteres acentuados ou especiais, como \"Este e um texto de exemplo\", ambos os formatos podem ser exibidos de forma idêntica em editores simples como o Bloco de Notas.\r\n<div>\r\n\r\n<hr />\r\n\r\n</div>\r\n<h3>Problema Prático</h3>\r\nSe você criar um arquivo de texto sem caracteres acentuados, como:\r\n<pre><code>$content = \"Este e um texto de exemplo. Sem caracteres especiais!\";</code></pre>\r\nEle será salvo corretamente em UTF-8, mas parecerá \"igual\" ao ser visualizado como ASCII, porque os caracteres usados pertencem à faixa básica compatível entre UTF-8 e ASCII.\r\n\r\nPorém, ao lidar com arquivos que precisam estar especificamente em ANSI, a conversão é necessária.\r\n<h3>Exemplo Completo em PHP</h3>\r\n<h4>Gerar um Arquivo UTF-8 e Convertê-lo para ANSI</h4>\r\nO seguinte script gera um arquivo <code>.txt</code> em UTF-8 e o converte para ANSI:\r\n\r\n\r\n<pre>&lt;?php\r\n\r\nfunction generateUtf8File($filePath, $content)\r\n{\r\n    // Gera um arquivo UTF-8\r\n    file_put_contents($filePath, $content);\r\n    echo \"Arquivo UTF-8 gerado em: $filePath\\n\";\r\n}\r\n\r\nfunction convertToAnsi($inputFile, $outputFile)\r\n{\r\n    // Verifica se o arquivo de entrada existe\r\n    if (!file_exists($inputFile)) {\r\n        throw new Exception(\"O arquivo de entrada não foi encontrado: $inputFile\");\r\n    }\r\n\r\n    // Lê o conteúdo do arquivo\r\n    $content = file_get_contents($inputFile);\r\n\r\n    // Converte o conteúdo para ANSI (ISO-8859-1)\r\n    $ansiContent = iconv(\"UTF-8\", \"ISO-8859-1//IGNORE\", $content);\r\n\r\n    // Grava o conteúdo convertido no arquivo de saída\r\n    file_put_contents($outputFile, $ansiContent);\r\n\r\n    echo \"Arquivo convertido para ANSI e salvo em: $outputFile\\n\";\r\n}\r\n\r\n// Caminhos dos arquivos\r\n$utf8File = \'arquivo_utf8.txt\';\r\n$ansiFile = \'arquivo_ansi.txt\';\r\n\r\n// Conteúdo do arquivo UTF-8\r\n$content = \"Este é um texto de exemplo. Sem caracteres especiais!\";\r\n\r\n// Gera o arquivo UTF-8\r\ngenerateUtf8File($utf8File, $content);\r\n\r\n// Converte para ANSI\r\ntry {\r\n    convertToAnsi($utf8File, $ansiFile);\r\n} catch (Exception $e) {\r\n    echo \"Erro: \" . $e-&gt;getMessage() . \"\\n\";</pre>\r\n\r\n<h4>Explicação do Código</h4>\r\n<ol start=\"1\">\r\n 	<li><strong>Função </strong><code><strong>generateUtf8File</strong></code>:\r\n<ul>\r\n 	<li>Gera um arquivo <code>.txt</code> com codificação UTF-8.</li>\r\n</ul>\r\n</li>\r\n 	<li><strong>Função </strong><code><strong>convertToAnsi</strong></code>:\r\n<ul>\r\n 	<li>Lê o arquivo criado.</li>\r\n 	<li>Usa a função <code>iconv</code> para converter o conteúdo de UTF-8 para ANSI (ISO-8859-1).</li>\r\n 	<li>Salva o arquivo convertido com um novo nome.</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n&nbsp;\r\n<h3>Por Que o Texto Sem Acentos Parece Igual em ANSI e UTF-8?</h3>\r\nArquivos sem caracteres especiais são exibidos corretamente porque:\r\n<ol start=\"1\">\r\n 	<li><strong>UTF-8 é compatível com ASCII</strong>:\r\n<ul>\r\n 	<li>Letras, números e pontuações na faixa de 0 a 127 são representados exatamente da mesma forma em ambas as codificações.</li>\r\n</ul>\r\n</li>\r\n 	<li><strong>O Bloco de Notas reconhece UTF-8 automaticamente</strong>:\r\n<ul>\r\n 	<li>Mesmo que o arquivo seja UTF-8, o Bloco de Notas interpreta corretamente caracteres básicos sem a necessidade de ajustes adicionais.</li>\r\n</ul>\r\n</li>\r\n 	<li><strong>Sem caracteres especiais, não há bytes adicionais</strong>:\r\n<ul>\r\n 	<li>A codificação não precisa de bytes extras para representar letras simples.</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n&nbsp;\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-01-22 10:27:21', 'published', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), content = VALUES(content), published_at = VALUES(published_at), status = VALUES(status);
