INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Entendendo a Função list() no PHP', 'entendendo-a-funcao-list-no-php', 'A função list() do PHP é uma forma prática de atribuir múltiplos valores de um array a variáveis individuais. Neste artigo, vamos explorar como essa função funciona, seus usos mais comuns e alternativas modernas…', '<p>A função <code>list()</code> do PHP é uma forma prática de atribuir múltiplos valores de um array a variáveis individuais. Neste artigo, vamos explorar como essa função funciona, seus usos mais comuns e alternativas modernas disponíveis no PHP.</p>\r\n\r\n<h2>O Que é a Função <code>list()</code>?</h2>\r\nA função <code>list()</code> permite extrair valores de um array e atribuí-los a variáveis individuais de maneira simplificada.\r\n<h3>Sintaxe Básica:</h3>\r\n\r\n<pre>list($var1, $var2, $var3) = array(valor1, valor2, valor3);</pre>\r\n\r\n<p>Cada variável recebe o valor correspondente da posição do array.</p>\r\n\r\n<h3>Exemplo de Uso:</h3>\r\n\r\n<pre>$dados = [\"Maria\", 30, \"Desenvolvedora\"];\r\nlist($nome, $idade, $profissao) = $dados;\r\n\r\necho \"Nome: $nome, Idade: $idade, Profissão: $profissao\";</pre>\r\n\r\n\r\nSaída:\r\n\r\n\r\n<pre>Nome: Maria, Idade: 30, Profissão: Desenvolvedora</pre>\r\n\r\n<h2>Importante: <code>list()</code> Só Funciona com Arrays Indexados</h2>\r\nA função <code>list()</code> <strong>não</strong> funciona com arrays associativos. Se você tentar usá-la com um array associativo, os valores não serão extraídos corretamente.\r\n\r\nExemplo que <strong>não funciona</strong>:\r\n\r\n\r\n<pre>$dados = [\"nome\" =&gt; \"Carlos\", \"idade\" =&gt; 25];\r\nlist($nome, $idade) = $dados; // Erro: valores indefinidos</pre>\r\n\r\n<h2>Ignorando Valores no <code>list()</code></h2>\r\nSe você quiser pular certos valores do array, pode omitir variáveis dentro de <code>list()</code>.\r\n\r\n\r\n<pre>$dados = [\"Ana\", \"Feminino\", 28];\r\nlist($nome, , $idade) = $dados;\r\n\r\necho \"Nome: $nome, Idade: $idade\";</pre>\r\n\r\n\r\nSaída:\r\n\r\n\r\n<pre>Nome: Ana, Idade: 28</pre>\r\n\r\n<h2>Uso Combinado com <code>explode()</code></h2>\r\n<code>list()</code> é muito útil ao trabalhar com strings separadas por delimitadores, como datas.\r\n\r\n\r\n<pre>$data = \"2025-03-11\";\r\nlist($ano, $mes, $dia) = explode(\"-\", $data);\r\n\r\necho \"Ano: $ano, Mês: $mes, Dia: $dia\";</pre>\r\n\r\n\r\nSaída:\r\n\r\n\r\n<pre>Ano: 2025, Mês: 03, Dia: 11</pre>\r\n\r\n<h2>Alternativa Moderna: Desestruturação com <code>[]</code></h2>\r\n<p>Desde o PHP 7.1, podemos usar <code>[]</code> para desestruturar arrays, substituindo <code>list()</code>.</p>\r\n<p></p>\r\n\r\n<pre>$valores = [10, 20, 30];\r\n[$a, $b, $c] = $valores;\r\n\r\necho \"A: $a, B: $b, C: $c\";</pre>\r\n<p></p>\r\n<p><strong>Saída:</strong></p>\r\n<p></p>\r\n\r\n<pre>A: 10, B: 20, C: 30</pre>\r\n<p></p>\r\n<p>Essa sintaxe é mais intuitiva e moderna.</p>\r\n<p>A função <code>list()</code> é útil para atribuir múltiplos valores de um array a variáveis de forma rápida. Entretanto, se estiver usando PHP 7.1 ou superior, prefira <code>[]</code> por ser uma alternativa mais moderna e legível.</p>\r\nSe gostou deste artigo, compartilhe com outros desenvolvedores e continue acompanhando mais dicas de PHP!\r\n\r\n&nbsp;\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-03-11 17:06:30', 'published', NULL)
