INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Usando Strategy e Pipeline juntos no Laravel para organizar regras complexas', 'usando-strategy-e-pipeline-juntos-no-laravel-para-organizar-regras-complexas', 'À medida que um sistema cresce, a lógica de negócio costuma se tornar mais complexa. Um dia você está apenas filtrando dados. No outro, está classificando, ordenando, eliminando, aplicando exceções e resolvendo empates.…', '<p>À medida que um sistema cresce, a lógica de negócio costuma se tornar mais complexa. Um dia você está apenas filtrando dados. No outro, está classificando, ordenando, eliminando, aplicando exceções e resolvendo empates. É aí que os padrões de projeto se tornam aliados poderosos para manter o código limpo e sustentável.</p>\r\n<p>Dois desses padrões se complementam muito bem: <strong>Strategy</strong> e <strong>Pipeline</strong>.</p>\r\n<p>Neste artigo, vamos explorar como esses dois padrões podem ser usados <strong>em conjunto</strong> no Laravel para organizar fluxos complexos de regras, como recomendações personalizadas, motores de classificação ou processamento condicional em múltiplas etapas.</p>\r\n\r\n<h2>Por que usar Strategy e Pipeline juntos?</h2>\r\n<p>Antes de ir para o código, é importante entender os papéis de cada padrão:</p>\r\n\r\n<ul>\r\n 	<li>\r\n<p><strong>Strategy</strong>: isola o <em>modo</em> de executar uma tarefa. Você pode ter diferentes estratégias para resolver o mesmo problema (ex: diferentes formas de recomendar, calcular, ou classificar). <strong>Se você quer conhecer um pouco mais sobre o padrão Strategy pode acessar Artigo :</strong> <a href=\"https://paulorb.dev/padrao-de-projeto-strategy-flexibilidade-e-eficiencia-no-design-de-software-com-php/\" target=\"_blank\" rel=\"noopener\">Padrão de Projeto Strategy: Flexibilidade e Eficiência no Design de Software com PHP</a></p>\r\n</li>\r\n 	<li>\r\n<p><strong>Pipeline</strong>: permite aplicar <em>várias operações sequenciais</em> sobre um dado. Você define um conjunto de etapas e aplica uma a uma.</p>\r\n</li>\r\n</ul>\r\n<p>Quando combinados, o <strong>Strategy</strong> define a lógica geral — <em>qual pipeline será usado</em> — e o <strong>Pipeline</strong> define a execução passo a passo das regras envolvidas.</p>\r\n\r\n<h2>Um exemplo prático: recomendação de cursos</h2>\r\n<p>Imagine que você está construindo um sistema que recomenda cursos para usuários com base em diversos critérios:</p>\r\n\r\n<ul>\r\n 	<li>\r\n<p>O nível do usuário (iniciante, intermediário, avançado)</p>\r\n</li>\r\n 	<li>\r\n<p>O tempo que ele tem disponível</p>\r\n</li>\r\n 	<li>\r\n<p>Seus temas de interesse</p>\r\n</li>\r\n 	<li>\r\n<p>A popularidade dos cursos</p>\r\n</li>\r\n</ul>\r\n<p>A regra pode variar entre usuários, e você pode ter diferentes formas de recomendação (ex: simples, personalizada, baseada em histórico).</p>\r\n\r\n<h2>Strategy: isolando os modos de recomendação</h2>\r\n<p>A primeira parte é criar uma interface comum para todas as estratégias de recomendação:</p>\r\n<p></p>\r\n\r\n<pre>namespace App\\Services\\Recomendacao\\Contracts;\r\n\r\ninterface RecomendacaoStrategy\r\n{\r\n    public function recomendar(array $cursos, array $usuario): array;\r\n}</pre>\r\n<p></p>\r\n<p>Em seguida, uma estratégia concreta personalizada, que vai usar o pipeline para executar as regras:</p>\r\n<p></p>\r\n\r\n<pre>namespace App\\Services\\Recomendacao\\Estrategias;\r\n\r\nuse App\\Services\\Recomendacao\\Contracts\\RecomendacaoStrategy;\r\nuse App\\Services\\Recomendacao\\Recomendador;\r\nuse App\\Services\\Recomendacao\\Pipelines\\FiltrarPorNivel;\r\nuse App\\Services\\Recomendacao\\Pipelines\\FiltrarPorTempoDisponivel;\r\nuse App\\Services\\Recomendacao\\Pipelines\\PriorizarInteresses;\r\nuse App\\Services\\Recomendacao\\Pipelines\\OrdenarPorPopularidade;\r\n\r\nclass RecomendacaoPersonalizada implements RecomendacaoStrategy\r\n{\r\n    public function __construct(\r\n        protected Recomendador $recomendador,\r\n        protected FiltrarPorNivel $filtroNivel,\r\n        protected FiltrarPorTempoDisponivel $filtroTempo,\r\n        protected PriorizarInteresses $priorizarInteresses,\r\n        protected OrdenarPorPopularidade $ordenarPopularidade,\r\n    ) {}\r\n\r\n    public function recomendar(array $cursos, array $usuario): array\r\n    {\r\n        return $this-&gt;recomendador\r\n            -&gt;com($cursos)\r\n            -&gt;paraUsuario($usuario)\r\n            -&gt;passandoPor([\r\n                $this-&gt;filtroNivel,\r\n                $this-&gt;filtroTempo,\r\n                $this-&gt;priorizarInteresses,\r\n                $this-&gt;ordenarPopularidade,\r\n            ])\r\n            -&gt;executar();\r\n    }\r\n}</pre>\r\n<p></p>\r\n\r\n<h2>Pipeline: executando regras em sequência</h2>\r\n<p>O Pipeline é quem executa as transformações, uma a uma, na ordem definida:</p>\r\n<p></p>\r\n\r\n<pre>namespace App\\Services\\Recomendacao;\r\n\r\nclass Recomendador\r\n{\r\n    protected array $cursos = [];\r\n    protected array $usuario = [];\r\n    protected array $etapas = [];\r\n\r\n    public function com(array $cursos): self\r\n    {\r\n        $this-&gt;cursos = $cursos;\r\n        return $this;\r\n    }\r\n\r\n    public function paraUsuario(array $usuario): self\r\n    {\r\n        $this-&gt;usuario = $usuario;\r\n        return $this;\r\n    }\r\n\r\n    public function passandoPor(array $etapas): self\r\n    {\r\n        $this-&gt;etapas = $etapas;\r\n        return $this;\r\n    }\r\n\r\n    public function executar(): array\r\n    {\r\n        return array_reduce(\r\n            $this-&gt;etapas,\r\n            fn($cursos, $etapa) =&gt; $etapa-&gt;handle($cursos, $this-&gt;usuario),\r\n            $this-&gt;cursos\r\n        );\r\n    }\r\n}</pre>\r\n<p></p>\r\n<p>Cada etapa é uma classe separada, fácil de testar, como neste exemplo:</p>\r\n<p></p>\r\n\r\n<pre>namespace App\\Services\\Recomendacao\\Pipelines;\r\n\r\nclass FiltrarPorNivel\r\n{\r\n    public function handle(array $cursos, array $usuario): array\r\n    {\r\n        return array_filter($cursos, fn($curso) =&gt; $curso[\'nivel\'] === $usuario[\'nivel\']);\r\n    }\r\n}</pre>\r\n<p></p>\r\n\r\n<h2>Resolvendo tudo via Service Container</h2>\r\n<p>No Laravel, é uma boa prática registrar a <strong>estratégia padrão</strong> no container. Assim, você injeta a interface no controller, e o Laravel cuida do resto:</p>\r\n<p></p>\r\n\r\n<pre>// App\\Providers\\AppServiceProvider.php\r\n\r\nuse App\\Services\\Recomendacao\\Contracts\\RecomendacaoStrategy;\r\nuse App\\Services\\Recomendacao\\Estrategias\\RecomendacaoPersonalizada;\r\n\r\npublic function register()\r\n{\r\n    $this-&gt;app-&gt;bind(RecomendacaoStrategy::class, function () {\r\n        return app(RecomendacaoPersonalizada::class);\r\n    });\r\n}</pre>\r\n<p></p>\r\n<p>No Controller: simples e limpo</p>\r\n<p></p>\r\n\r\n<pre>use App\\Services\\Recomendacao\\Contracts\\RecomendacaoStrategy;\r\n\r\nclass CursoController extends Controller\r\n{\r\n    public function recomendar(RecomendacaoStrategy $estrategia)\r\n    {\r\n        $usuario = auth()-&gt;user()-&gt;toArray();\r\n        $cursos = Curso::all()-&gt;toArray();\r\n\r\n        $recomendados = $estrategia-&gt;recomendar($cursos, $usuario);\r\n\r\n        return view(\'cursos.recomendados\', compact(\'recomendados\'));\r\n    }\r\n}</pre>\r\n<p></p>\r\n\r\n<h2>Vantagens reais da combinação Strategy + Pipeline</h2>\r\n<p>Ao combinar Strategy com Pipeline, você ganha:</p>\r\n<p>✅ <strong>Separação clara de responsabilidades</strong><br />Strategy define <em>o que fazer</em>, Pipeline define <em>como fazer passo a passo</em>.</p>\r\n<p>✅ <strong>Extensibilidade</strong><br />Você pode adicionar novas estratégias ou novas etapas sem quebrar nada.</p>\r\n<p>✅ <strong>Testabilidade</strong><br />Cada etapa pode ser testada de forma isolada.</p>\r\n<p>✅ <strong>Injeção automática</strong><br />A estratégia e suas dependências são resolvidas pelo container do Laravel.</p>\r\n\r\n<h2>Conclusão</h2>\r\n<p>Combinar Strategy e Pipeline é uma forma poderosa de lidar com lógicas complexas e altamente variáveis em sistemas Laravel. Com Strategy, você pode trocar facilmente o comportamento global. Com Pipeline, você define fluxos reutilizáveis, testáveis e organizados.</p>\r\n<p>Se você trabalha com regras que envolvem múltiplas etapas — como classificação, recomendação, filtragem ou processamento — essa abordagem pode deixar seu código muito mais limpo e preparado para o crescimento.</p>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-06-16 14:45:41', 'published', NULL)
