VALUES ('De jQuery para Alpine.js: Um Guia Prático com Laravel e Componentes Reutilizáveis', 'de-jquery-para-alpine-js-um-guia-pratico-com-laravel-e-componentes-reutilizaveis', 'Se você vem do jQuery e quer modernizar seus projetos com Alpine.js, esse tutorial é pra você. Vamos mostrar como sair de ações comuns com jQuery e aplicá-las com Alpine.js, e no final, criar um mini projeto real com…', '<p>Se você vem do jQuery e quer modernizar seus projetos com <strong>Alpine.js</strong>, esse tutorial é pra você. Vamos mostrar como sair de ações comuns com jQuery e aplicá-las com Alpine.js, e no final, criar um <strong>mini projeto real com Laravel</strong> usando formulários reativos e requisições AJAX limpas.</p>\r\n\r\n<h2>Alpine.js vs jQuery: Conceitos Fundamentais</h2>\r\n<p>Alpine.js é um mini framework reativo pensado para funcionar direto no HTML, como o jQuery, mas com uma pegada declarativa e moderna.</p>\r\n\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>Conceito</th>\r\n<th>jQuery</th>\r\n<th>Alpine.js</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>DOM Ready</td>\r\n<td><code>$(document).ready(...)</code></td>\r\n<td><code>x-data</code> inicializa automaticamente</td>\r\n</tr>\r\n<tr>\r\n<td>Mostrar/ocultar</td>\r\n<td><code>$(\'#id\').hide()</code></td>\r\n<td><code>x-show=\"visivel\"</code></td>\r\n</tr>\r\n<tr>\r\n<td>Eventos</td>\r\n<td><code>$(\'#btn\').click(...)</code></td>\r\n<td><code>@click=\"acao()\"</code></td>\r\n</tr>\r\n<tr>\r\n<td>Acesso a valores</td>\r\n<td><code>$(\'#input\').val()</code></td>\r\n<td><code>x-model=\"valor\"</code></td>\r\n</tr>\r\n<tr>\r\n<td>AJAX</td>\r\n<td><code>$.get(...)</code>, <code>$.post(...)</code></td>\r\n<td><code>fetch(...)</code>, com ou sem async/await</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<strong>Exemplos Comparativos</strong>\r\n\r\n<strong>1. Manipular formulário</strong>\r\n\r\n<strong><em>Jquery</em></strong>\r\n\r\n\r\n<pre>$(\'#btn\').click(() =&gt; {\r\n    const nome = $(\'#nome\').val();\r\n    alert(\'Olá \' + nome);\r\n});\r\n</pre>\r\n\r\n\r\n<em><strong>Alpine</strong></em>\r\n\r\n\r\n<pre>&lt;div x-data=\"{ nome: \'\' }\"&gt;\r\n    &lt;input x-model=\"nome\" placeholder=\"Digite seu nome\"&gt;\r\n    &lt;button @click=\"alert(\'Olá \' + nome)\"&gt;Enviar&lt;/button&gt;\r\n&lt;/div&gt;</pre>\r\n\r\n\r\n2. AJAX (GET)\r\n\r\njQuery\r\n\r\n\r\n<pre>$.get(\'/api/usuarios\', function(data) {\r\n    console.log(data);\r\n});</pre>\r\n\r\n\r\nAlpine\r\n\r\n\r\n<pre>&lt;div x-data=\"{\r\n    usuarios: [],\r\n    async carregar() {\r\n        const res = await fetch(\'/api/usuarios\');\r\n        this.usuarios = await res.json();\r\n    }\r\n}\" x-init=\"carregar()\"&gt;\r\n    &lt;ul&gt;\r\n        &lt;template x-for=\"user in usuarios\"&gt;\r\n            &lt;li x-text=\"user.nome\"&gt;&lt;/li&gt;\r\n        &lt;/template&gt;\r\n    &lt;/ul&gt;\r\n&lt;/div&gt;</pre>\r\n\r\n\r\n3. POST com Alpine + Fetch\r\n\r\n\r\n<pre>&lt;div x-data=\"{\r\n    nome: \'\',\r\n    async salvar() {\r\n        await fetch(\'/api/usuarios\', {\r\n            method: \'POST\',\r\n            headers: { \'Content-Type\': \'application/json\' },\r\n            body: JSON.stringify({ nome: this.nome })\r\n        });\r\n    }\r\n}\"&gt;\r\n    &lt;input x-model=\"nome\"&gt;\r\n    &lt;button @click=\"salvar\"&gt;Salvar&lt;/button&gt;\r\n&lt;/div&gt;</pre>\r\n\r\n\r\nAgora Vamos a um mini projeto para aplicarmos na prática:\r\n\r\n<strong>Mini Projeto: Alpine.js + Laravel com Formulário Dinâmico</strong>\r\n<h3>🧱 Estrutura</h3>\r\n<ul>\r\n 	<li>\r\n<p>Backend: Laravel 12</p>\r\n</li>\r\n 	<li>\r\n<p>Frontend: Blade + Alpine.js (separado)</p>\r\n</li>\r\n 	<li>\r\n<p>Objetivo: Cadastrar e listar usuários com AJAX</p>\r\n</li>\r\n</ul>\r\n<h3>1️⃣ Laravel – Migration e Controller</h3>\r\n<p><strong>Migration:</strong></p>\r\n<p></p>\r\n\r\n<pre>php artisan make:model Usuario -m</pre>\r\n<p></p>\r\n<p></p>\r\n\r\n<pre>Schema::create(\'usuarios\', function (Blueprint $table) {\r\n    $table-&gt;id();\r\n    $table-&gt;string(\'nome\');\r\n    $table-&gt;string(\'email\')-&gt;unique();\r\n    $table-&gt;timestamps();\r\n});</pre>\r\n<p></p>\r\n<p></p>\r\n\r\n<pre>php artisan migrate</pre>\r\n<p></p>\r\n<p><strong>Controller:</strong></p>\r\n<p></p>\r\n\r\n<pre>public function index() {\r\n    return Usuario::all();\r\n}\r\n\r\npublic function store(Request $request) {\r\n    $dados = $request-&gt;validate([\r\n        \'nome\' =&gt; \'required\',\r\n        \'email\' =&gt; \'required|email|unique:usuarios\',\r\n    ]);\r\n\r\n    return Usuario::create($dados);\r\n}</pre>\r\n<p></p>\r\n<p><strong>Rotas (API):</strong></p>\r\n<p></p>\r\n\r\n<pre>Route::get(\'/usuarios\', [UsuarioController::class, \'index\']);\r\nRoute::post(\'/usuarios\', [UsuarioController::class, \'store\']);</pre>\r\n<p></p>\r\n<p>2️⃣ <strong>Alpine.js – Componente externo</strong></p>\r\n<p><code>resources/js/components/usuarioForm.js</code>:</p>\r\n<p></p>\r\n\r\n<pre>export default function usuarioForm() {\r\n    return {\r\n        form: { nome: \'\', email: \'\' },\r\n        usuarios: [],\r\n        mensagem: \'\',\r\n        async salvar() {\r\n            const res = await fetch(\'/api/usuarios\', {\r\n                method: \'POST\',\r\n                headers: {\r\n                    \'Content-Type\': \'application/json\',\r\n                    \'X-CSRF-TOKEN\': document.querySelector(\'meta[name=\"csrf-token\"]\').content,\r\n                },\r\n                body: JSON.stringify(this.form)\r\n            });\r\n            this.mensagem = \'Usuário cadastrado com sucesso!\';\r\n            this.form.nome = \'\';\r\n            this.form.email = \'\';\r\n            this.carregar();\r\n        },\r\n        async carregar() {\r\n            const res = await fetch(\'/api/usuarios\');\r\n            this.usuarios = await res.json();\r\n        },\r\n        init() {\r\n            this.carregar();\r\n        }\r\n    }\r\n}\r\n</pre>\r\n<p></p>\r\n<p><strong>3️⃣ Alpine + Vite</strong></p>\r\n<code>resources/js/app.js</code>:\r\n\r\n\r\n<pre>import Alpine from \'alpinejs\';\r\nimport usuarioForm from \'./components/usuarioForm\';\r\n\r\nwindow.Alpine = Alpine;\r\nAlpine.data(\'usuarioForm\', usuarioForm);\r\n\r\nAlpine.start();</pre>\r\n\r\n\r\n4️⃣ Blade com Alpine.js\r\n\r\n\r\n<pre>&lt;!DOCTYPE html&gt;\r\n&lt;html lang=\"pt-BR\"&gt;\r\n&lt;head&gt;\r\n    &lt;meta charset=\"UTF-8\"&gt;\r\n    &lt;meta name=\"csrf-token\" content=\"{{ csrf_token() }}\"&gt;\r\n    &lt;title&gt;Usuários&lt;/title&gt;\r\n    @vite(\'resources/js/app.js\')\r\n&lt;/head&gt;\r\n&lt;body&gt;\r\n\r\n&lt;div x-data=\"usuarioForm\"&gt;\r\n    &lt;form @submit.prevent=\"salvar\"&gt;\r\n        &lt;input x-model=\"form.nome\" placeholder=\"Nome\"&gt;\r\n        &lt;input x-model=\"form.email\" placeholder=\"Email\"&gt;\r\n        &lt;button type=\"submit\"&gt;Salvar&lt;/button&gt;\r\n    &lt;/form&gt;\r\n\r\n    &lt;div x-text=\"mensagem\" x-show=\"mensagem\"&gt;&lt;/div&gt;\r\n\r\n    &lt;h3&gt;Usuários:&lt;/h3&gt;\r\n    &lt;ul&gt;\r\n        &lt;template x-for=\"u in usuarios\" :key=\"u.id\"&gt;\r\n            &lt;li&gt;&lt;strong x-text=\"u.nome\"&gt;&lt;/strong&gt; - &lt;span x-text=\"u.email\"&gt;&lt;/span&gt;&lt;/li&gt;\r\n        &lt;/template&gt;\r\n    &lt;/ul&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;/body&gt;\r\n&lt;/html&gt;</pre>\r\n\r\n<h2>Conclusão</h2>\r\n<p>Se você já domina jQuery, Alpine.js é o passo natural para criar interfaces mais modernas, reativas e organizadas, <strong>sem sair do Blade</strong> e sem complicações como Vue ou React.</p>\r\n<p>Com Alpine, você ganha:</p>\r\n\r\n<ul>\r\n 	<li>\r\n<p>Reatividade nativa no HTML</p>\r\n</li>\r\n 	<li>\r\n<p>Menos código JS separado</p>\r\n</li>\r\n 	<li>\r\n<p>Facilidade para integrar com Laravel e Livewire</p>\r\n</li>\r\n 	<li>\r\n<p>Menor curva de aprendizado vindo do jQuery</p>\r\n</li>\r\n</ul>\r\n&nbsp;\r\n\r\n&nbsp;\r\n\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-06-20 10:39:03', 'published', NULL)
