INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('🔍Laravel: Eloquent vs Query Builder — Qual usar para cada situação?', '%f0%9f%94%8dlaravel-eloquent-vs-query-builder-qual-usar-para-cada-situacao', 'No ecossistema Laravel, há duas formas principais de interagir com o banco de dados: o Eloquent ORM e o Query Builder. Ambos têm seu espaço, mas entender quando usar cada um é essencial para escrever código limpo,…', '<p>No ecossistema Laravel, há duas formas principais de interagir com o banco de dados: o <strong>Eloquent ORM</strong> e o <strong>Query Builder</strong>. Ambos têm seu espaço, mas entender <strong>quando usar cada um</strong> é essencial para escrever código limpo, performático e fácil de manter.</p>\r\n<p>Neste artigo, vamos comparar essas duas abordagens, mostrar exemplos reais de uso e apontar os cenários ideais para cada uma delas. Vamos nessa?</p>\r\n\r\n<h2>O que é o Eloquent?</h2>\r\n<p>O <strong>Eloquent</strong> é o ORM (Object-Relational Mapper) oficial do Laravel. Ele transforma tabelas em <strong>classes PHP</strong>, permitindo que você trabalhe com os dados como objetos.</p>\r\n<p>Cada model representa uma tabela, e cada instância do model representa uma linha. Por trás das cortinas, o Eloquent é construído sobre o Query Builder, mas com uma interface orientada a objetos.</p>\r\n\r\n<h3>Exemplo real:</h3>\r\n\r\n<pre>$candidato = Candidato::where(\'cpf\', \'123.456.789-00\')-&gt;first();\r\n</pre>\r\n\r\n<h3>Recursos do Eloquent:</h3>\r\n<ul>\r\n 	<li>\r\n<p>Relacionamentos (<code>hasMany</code>, <code>belongsTo</code>, etc.)</p>\r\n</li>\r\n 	<li>\r\n<p>Eventos (<code>creating</code>, <code>updated</code>, etc.)</p>\r\n</li>\r\n 	<li>\r\n<p>Casts de atributos</p>\r\n</li>\r\n 	<li>\r\n<p>Accessors e mutators</p>\r\n</li>\r\n 	<li>\r\n<p>Soft deletes</p>\r\n</li>\r\n 	<li>\r\n<p>Timestamps automáticos</p>\r\n</li>\r\n</ul>\r\n<h2>O que é o Query Builder?</h2>\r\n<p>O <strong>Query Builder</strong> oferece uma forma fluente e segura de construir queries SQL diretamente, sem precisar criar models.</p>\r\n<p>Ele é ótimo para <strong>consultas complexas</strong>, <strong>operações em massa</strong> ou quando você precisa de <strong>performance</strong> e <strong>controle granular</strong> da query.</p>\r\n\r\n<h3>Exemplo real:</h3>\r\n\r\n<pre>$relatorio = DB::table(\'inscricoes\')\r\n    -&gt;select(\'cargo_id\', DB::raw(\'count(*) as total\'))\r\n    -&gt;where(\'status\', \'deferido\')\r\n    -&gt;groupBy(\'cargo_id\')\r\n    -&gt;get();\r\n</pre>\r\n\r\n<h2>Comparativo: Eloquent vs Query Builder</h2>\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>Critério</th>\r\n<th><strong>Eloquent</strong></th>\r\n<th><strong>Query Builder</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>Retorno</td>\r\n<td>Modelos (objetos com métodos)</td>\r\n<td>Objetos <code>stdClass</code></td>\r\n</tr>\r\n<tr>\r\n<td>Relacionamentos</td>\r\n<td>Sim</td>\r\n<td>Não</td>\r\n</tr>\r\n<tr>\r\n<td>Lógica encapsulada</td>\r\n<td>Sim</td>\r\n<td>Não</td>\r\n</tr>\r\n<tr>\r\n<td>Eventos (<code>creating</code>, etc.)</td>\r\n<td>Sim</td>\r\n<td>Não</td>\r\n</tr>\r\n<tr>\r\n<td>Performance</td>\r\n<td>Mais pesado</td>\r\n<td>Mais leve e rápido</td>\r\n</tr>\r\n<tr>\r\n<td>Facilidade para joins</td>\r\n<td>Limitada</td>\r\n<td>Muito flexível</td>\r\n</tr>\r\n<tr>\r\n<td>Ideal para</td>\r\n<td>CRUDs com lógica de negócio</td>\r\n<td>Relatórios, queries otimizadas</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h2>Operações CRUD: Exemplos práticos</h2>\r\n<h3>Criar um registro</h3>\r\n<strong>Eloquent:</strong>\r\n\r\n\r\n<pre>Pedido::create([\r\n    \'candidato_id\' =&gt; 1,\r\n    \'tipo\' =&gt; \'isenção\',\r\n    \'status\' =&gt; \'em análise\',\r\n]);\r\n</pre>\r\n\r\n\r\n<strong>Query Builder</strong>\r\n\r\n\r\n<pre>DB::table(\'pedidos\')-&gt;insert([\r\n    \'candidato_id\' =&gt; 1,\r\n    \'tipo\' =&gt; \'isenção\',\r\n    \'status\' =&gt; \'em análise\',\r\n]);\r\n</pre>\r\n\r\n<h3>Atualizar registros</h3>\r\n<h4>Atualizar um único registro</h4>\r\n<p><strong>Eloquent:</strong></p>\r\n<p></p>\r\n\r\n<pre>$pedido = Pedido::find(10);\r\n$pedido-&gt;status = \'deferido\';\r\n$pedido-&gt;save();\r\n</pre>\r\n<p></p>\r\n<p><strong>Query Builder:</strong></p>\r\n<p></p>\r\n\r\n<pre>DB::table(\'pedidos\')\r\n    -&gt;where(\'id\', 10)\r\n    -&gt;update([\'status\' =&gt; \'deferido\']);</pre>\r\n<p></p>\r\n<p>Atualização em massa</p>\r\n<p></p>\r\n\r\n<pre>// Query Builder é mais eficiente nesse caso\r\nDB::table(\'pedidos\')\r\n    -&gt;where(\'status\', \'em análise\')\r\n    -&gt;update([\'status\' =&gt; \'indeferido\']);\r\n</pre>\r\n<p></p>\r\n\r\n<h3>Excluir registros</h3>\r\n<p><strong>Eloquent com soft delete:</strong></p>\r\n<p></p>\r\n\r\n<pre>Candidato::find($id)-&gt;delete();</pre>\r\n<p></p>\r\n<p><strong>Query Builder direto:</strong></p>\r\n<p></p>\r\n\r\n<pre>DB::table(\'candidatos\')-&gt;where(\'id\', $id)-&gt;delete();\r\n</pre>\r\n<p></p>\r\n\r\n<h2>Quando usar cada um?</h2>\r\n<h3>Use <strong>Eloquent</strong> quando:</h3>\r\n<ul>\r\n 	<li>\r\n<p>Trabalhar com <strong>entidades de domínio</strong> (ex: <code>Usuario</code>, <code>Pedido</code>, <code>Candidato</code>)</p>\r\n</li>\r\n 	<li>\r\n<p>Precisar de <strong>relacionamentos</strong></p>\r\n</li>\r\n 	<li>\r\n<p>Houver lógica de negócio acoplada ao dado (validações, métodos, regras)</p>\r\n</li>\r\n 	<li>\r\n<p>Quiser manter o código mais expressivo e OO</p>\r\n</li>\r\n</ul>\r\n<h3>Use <strong>Query Builder</strong> quando:</h3>\r\n<ul>\r\n 	<li>\r\n<p>Estiver fazendo <strong>consultas com <code>join</code>, <code>groupBy</code>, <code>having</code></strong>, etc.</p>\r\n</li>\r\n 	<li>\r\n<p>Precisar de <strong>performance em consultas de grandes volumes</strong></p>\r\n</li>\r\n 	<li>\r\n<p>Estiver lidando com <strong>scripts administrativos</strong></p>\r\n</li>\r\n 	<li>\r\n<p>Não houver necessidade de criar um model (ex: relatórios ou dashboard)</p>\r\n</li>\r\n</ul>\r\n<h2>Dicas práticas</h2>\r\n<ul>\r\n 	<li>\r\n<p><strong>Evite carregar muitos registros com Eloquent</strong> se você não for usá-los como objetos. Prefira o <code>Query Builder</code> nesse caso.</p>\r\n</li>\r\n 	<li>\r\n<p>Use <code>select()</code> no Eloquent para reduzir colunas carregadas:</p>\r\n</li>\r\n</ul>\r\n\r\n<pre>Candidato::select(\'id\', \'nome\')-&gt;get();</pre>\r\n\r\n\r\nPara casos híbridos (ex: usar Eloquent mas com joins manuais), você também pode usar:\r\n\r\n\r\n<pre>Pedido::join(\'candidatos\', \'candidatos.id\', \'=\', \'pedidos.candidato_id\')\r\n    -&gt;select(\'pedidos.*\', \'candidatos.nome\')\r\n    -&gt;get();</pre>\r\n\r\n<p>O Laravel te dá a liberdade de escolher entre <strong>Eloquent</strong> e <strong>Query Builder</strong> dependendo da necessidade. Em geral:</p>\r\n\r\n<ul>\r\n 	<li>\r\n<p><strong>Eloquent</strong> é ideal para <strong>domínio rico</strong>, com regras e relacionamentos.</p>\r\n</li>\r\n 	<li>\r\n<p><strong>Query Builder</strong> é melhor para <strong>performance, relatórios e manipulação em massa</strong>.</p>\r\n</li>\r\n</ul>\r\n<p>A chave está em entender a <strong>intenção da operação</strong>. Se for sobre um \"objeto do seu negócio\", Eloquent. Se for só \"dados\", talvez o Query Builder seja mais adequado.</p>\r\n\r\n<h2>Fontes e leitura complementar</h2>\r\n<ul>\r\n 	<li>\r\n<p><a href=\"https://laravel.com/docs/eloquent\" target=\"_new\" rel=\"noopener\">Documentação do Eloquent ORM (Laravel)</a></p>\r\n</li>\r\n 	<li>\r\n<p><a href=\"https://laravel.com/docs/queries\" target=\"_new\" rel=\"noopener\">Documentação do Query Builder (Laravel)</a></p>\r\n</li>\r\n 	<li>\r\n<p><a target=\"_new\" rel=\"noopener\">Eloquent Performance Tips - Laracasts</a></p>\r\n</li>\r\n</ul>\r\n<p></p>', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-07-04 14:25:11', 'published', NULL)
