INSERT INTO posts (title, slug, excerpt, content, author_name, author_id, featured_image, published_at, status, deleted_at)
VALUES ('Como rodar Laravel no WSL com Valet Linux (de verdade)', 'como-rodar-laravel-no-wsl-com-valet-linux-de-verdade', 'Sim, dá pra desenvolver Laravel no Windows sem sofrer. Mas você precisa fazer do jeito certo: usando WSL + Valet Linux. Esqueça XAMPP, Laragon, Docker lento e até o WSL 1. O caminho mais fluido para trabalhar com…', 'Sim, dá pra desenvolver Laravel no Windows sem sofrer. Mas você precisa fazer do jeito certo: usando <strong>WSL + Valet Linux</strong>.\r\n\r\nEsqueça XAMPP, Laragon, Docker lento e até o WSL 1. O caminho mais fluido para trabalhar com Laravel no Windows hoje é rodar o ambiente <strong>nativamente no Linux, dentro do Windows</strong>, com o poder do Valet.\r\n\r\n<strong>Spoiler:</strong> no final você acessa <code>http://meusite.test</code> no Chrome como se estivesse no Linux nativo. E funciona rápido.\r\n<p><strong>Pré-requisitos</strong></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p><strong>Windows 10/11</strong></p>\r\n</li>\r\n 	<li>\r\n<p><strong>WSL2 habilitado</strong></p>\r\n</li>\r\n 	<li>\r\n<p><strong>Ubuntu instalado no WSL</strong></p>\r\n</li>\r\n 	<li>\r\n<p>PHP 8.3+</p>\r\n</li>\r\n 	<li>\r\n<p>Composer</p>\r\n</li>\r\n 	<li>\r\n<p>Git</p>\r\n</li>\r\n</ul>\r\n<p>Se não tem isso ainda, <a href=\"https://learn.microsoft.com/pt-br/windows/wsl/install\" target=\"_new\" rel=\"noopener\">instala o WSL aqui primeiro</a>.</p>\r\n<p><strong>1. Instalando o Valet Linux</strong></p>\r\n<p></p>\r\n\r\n<pre>composer global require cpriego/valet-linux\r\n</pre>\r\n<p></p>\r\n<p>Adicione o bin do composer ao seu PATH no <code>~/.bashrc</code> ou <code>~/.zshrc</code>:</p>\r\n<p></p>\r\n\r\n<pre>export PATH=\"$HOME/.config/composer/vendor/bin:$PATH\"</pre>\r\n<p></p>\r\n<p>Depois rode:</p>\r\n<p></p>\r\n\r\n<pre>valet install</pre>\r\n<p></p>\r\n<p>Erro? Provavelmente ele pediu algumas dependências. Instala elas:</p>\r\n<p></p>\r\n\r\n<pre>sudo apt install jq xsel libnss3-tools -y</pre>\r\n<p></p>\r\n<p>E instala o NGINX também, caso não esteja:</p>\r\n<p></p>\r\n\r\n<pre>sudo apt install nginx dnsmasq -y</pre>\r\n<p></p>\r\n<p>Aí sim:</p>\r\n<p></p>\r\n\r\n<pre>valet install</pre>\r\n<p></p>\r\n<p><strong>2. Criando e servindo seus projetos Laravel</strong></p>\r\n<p>Crie uma pasta para seus projetos:</p>\r\n<p></p>\r\n\r\n<pre>mkdir ~/Desenvolvimento\r\ncd ~/Desenvolvimento\r\nvalet park</pre>\r\n<p></p>\r\n<p>Agora crie ou clone seu projeto:</p>\r\n<p></p>\r\n\r\n<pre>laravel new corretagem-novo\r\ncd corretagem-novo\r\nvalet link</pre>\r\n<p></p>\r\n<p>Acesse:</p>\r\n<p></p>\r\n\r\n<pre>http://corretagem-novo.test</pre>\r\n<p></p>\r\n<p>Sim. <code>.test</code> funcionando, direto no navegador do Windows.</p>\r\n<strong>3. “DNS_PROBE_FINISHED_NXDOMAIN”? É o WSL…</strong>\r\n\r\nVocê precisa mapear o domínio <code>.test</code> para o IP do WSL no Windows.\r\n\r\nNo terminal WSL:\r\n\r\n\r\n<pre>ip addr show eth0 | grep inet</pre>\r\n\r\n\r\nVai dar algo como:\r\n\r\n\r\n<pre>inet 172.28.81.23/20 ...</pre>\r\n\r\n<p>Copie o IP.</p>\r\n<p>Agora, no <strong>Windows</strong>, edite o arquivo <code>hosts</code> como administrador:</p>\r\n<p></p>\r\n\r\n<pre>C:\\Windows\\System32\\drivers\\etc\\hosts</pre>\r\n<p></p>\r\n<p>Adicione:</p>\r\n<p></p>\r\n\r\n<pre>172.28.81.23  corretagem-novo.test</pre>\r\n<p></p>\r\n<p><strong>Bonus: Dicas rápidas</strong></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p><code>valet use 8.2&gt;=</code>: troca a versão do PHP</p>\r\n</li>\r\n 	<li>\r\n<p><code>valet secure meuapp</code>: ativa HTTPS pro projeto</p>\r\n</li>\r\n 	<li>\r\n<p><code>valet tinker</code>: shell PHP direto</p>\r\n</li>\r\n 	<li>\r\n<p><code>valet share</code>: ngrok instantâneo (para mostrar o projeto ao cliente)</p>\r\n</li>\r\n</ul>\r\n&nbsp;', 'Paulo Bolsanello', (SELECT id FROM users WHERE email = 'paulo.bolsanello@gmail.com' LIMIT 1), '/assets/images/blog-feature.svg', '2025-07-20 12:05:22', 'published', NULL)
